import React from 'react';
import { Play, ArrowRight, ArrowLeft, FileText, RefreshCw, FolderOpen, CheckCircle2 } from 'lucide-react';
import * as S from './Settings.styled';

export type FileListStatus = 'loading' | 'ready' | 'error';
interface SettingsViewProps {
  step: number;
  isRunning: boolean;
  progress: number;
  progressMessage: string;
  totalQueries: number;
  recoveryNeeded?: boolean;
  requestLabel?: string;
  requestMessage?: string;
  handleCheckResults?: () => void;
  handleOpenDashboard?: () => void;
  handlePrepareNewRun?: () => void;
  inputMode: 'llm-generated' | 'custom';
  setInputMode: (mode: 'llm-generated' | 'custom') => void;
  serverFiles: string[];
  fileStatus: FileListStatus;
  error: string;
  selectedFileName: string;
  setSelectedFileName: (fileName: string) => void;
  handleNextStep: () => void;
  handlePrevStep: () => void;
  handleRefresh: () => void;
}

export const SettingsView: React.FC<SettingsViewProps> = ({
  step,
  isRunning,
  progress,
  progressMessage,
  totalQueries,
  recoveryNeeded,
  requestLabel,
  requestMessage,
  handleCheckResults,
  handleOpenDashboard,
  handlePrepareNewRun,
  inputMode,
  setInputMode,
  serverFiles,
  fileStatus,
  error,
  selectedFileName,
  setSelectedFileName,
  handleNextStep,
  handlePrevStep,
  handleRefresh,
}) => {
  const validSelection = fileStatus === 'ready' && serverFiles.includes(selectedFileName);
  return (
    <S.SettingsContainer>
      <S.Header>
        <span>BATCH EVALUATION</span>
        <h1>여러 질문을 한 번에 평가하세요</h1>
        <p>
          서버에 준비된 질문 파일을 선택해 같은 RAG 흐름을 실행합니다. 완료 후 대시보드에서 질문별 결과와 실패 원인을
          확인할 수 있습니다.
        </p>
      </S.Header>
      <S.Steps aria-label="일괄 평가 순서">
        <li aria-current={!isRunning && step === 1 ? 'step' : undefined}>
          <b>{step > 1 ? <CheckCircle2 size={15} /> : 1}</b>
          <span>질문 소스 선택</span>
        </li>
        <li aria-current={!isRunning && step === 2 ? 'step' : undefined}>
          <b>2</b>
          <span>파일 선택 · 실행</span>
        </li>
        <li aria-current={isRunning ? 'step' : undefined}>
          <b>3</b>
          <span>평가 · 결과 확인</span>
        </li>
      </S.Steps>
      {error && <S.Alert role="alert">{error}</S.Alert>}
      {requestLabel && (
        <S.Note role="status" style={{ margin: '0 0 16px' }}>
          <strong>{requestLabel}</strong> · {requestMessage}
          <br />
          요청 번호는 이 탭의 전송 순서이며, 실행 번호·질문 번호와는 다릅니다.
        </S.Note>
      )}
      <S.FormContainer aria-busy={isRunning}>
        {recoveryNeeded ? (
          <>
            <S.Title>실행 완료 여부를 다시 확인해 주세요</S.Title>
            <S.Description>
              같은 요청 ID의 처리 상태와 저장 기록을 확인합니다. 서버에서 상태를 알 수 없으면 완료나 실패로 단정하지
              않습니다. 실행 요청을 자동으로 다시 보내지는 않습니다.
            </S.Description>
            <S.Note>
              저장된 결과를 확인하거나 결과를 다시 불러오세요. 새 요청을 준비해도 기존 평가는 취소되지 않으며 서버에서
              계속 처리될 수 있습니다.
            </S.Note>
            <S.ButtonWrapper>
              <S.BackButton type="button" onClick={handleCheckResults}>
                <RefreshCw size={15} />
                결과 다시 불러오기
              </S.BackButton>
              <S.SubmitButton type="button" onClick={handleOpenDashboard}>
                <ArrowRight size={15} />
                저장된 결과 확인
              </S.SubmitButton>
            </S.ButtonWrapper>
            <S.RefreshButton type="button" onClick={handlePrepareNewRun}>
              기존 평가 유지하고 새 요청 준비
            </S.RefreshButton>
          </>
        ) : isRunning ? (
          <>
            <S.Title>{totalQueries > 0 ? '질문별 평가를 진행하고 있습니다' : '서버에 실행을 요청했습니다'}</S.Title>
            <S.Description>
              평가가 끝나면 결과 대시보드로 이동합니다. 실행 실패한 질문도 진단 기록에 포함됩니다.
            </S.Description>
            <S.Note style={{ marginTop: 0 }}>
              선택한 파일 <strong style={{ color: 'var(--text)' }}>{selectedFileName || '서버에서 시작된 실행'}</strong>
            </S.Note>
            <S.ProgressTrack
              role="progressbar"
              aria-label="질문 평가 진행률"
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={totalQueries > 0 ? progress : undefined}
              data-pending={totalQueries <= 0}
            >
              <div style={{ width: `${progress}%` }} />
            </S.ProgressTrack>
            <S.ProgressInfo role="status" aria-live="polite">
              <span>{progressMessage || '실행 시작 응답을 기다리고 있습니다.'}</span>
              {totalQueries > 0 && <strong>{progress}%</strong>}
            </S.ProgressInfo>
          </>
        ) : (
          <>
            {step === 1 ? (
              <>
                <S.Title>어떤 질문 파일을 사용할까요?</S.Title>
                <S.Description>
                  질문 소스는 파일이 저장된 위치를 구분합니다. 이 화면에서 새 질문을 생성하거나 파일을 업로드하지는
                  않습니다.
                </S.Description>
                <S.Fieldset>
                  <legend>질문 파일 소스</legend>
                  <S.Grid>
                    <S.OptionBox $selected={inputMode === 'custom'}>
                      <input
                        type="radio"
                        name="input-mode"
                        value="custom"
                        checked={inputMode === 'custom'}
                        onChange={() => setInputMode('custom')}
                      />
                      <div>
                        <strong>직접 준비한 질문</strong>
                        <small>프로젝트의 custom 폴더에 저장한 질문 파일을 선택합니다.</small>
                      </div>
                    </S.OptionBox>
                    <S.OptionBox $selected={inputMode === 'llm-generated'}>
                      <input
                        type="radio"
                        name="input-mode"
                        value="llm-generated"
                        checked={inputMode === 'llm-generated'}
                        onChange={() => setInputMode('llm-generated')}
                      />
                      <div>
                        <strong>미리 생성한 질문</strong>
                        <small>query-gen으로 만든 뒤 generated 폴더에 저장된 파일을 선택합니다.</small>
                      </div>
                    </S.OptionBox>
                  </S.Grid>
                </S.Fieldset>
                <S.Note>
                  질문 하나만 빠르게 확인하려면 메뉴의 ‘실시간 검증’을 사용하세요. 선택한 RAG 흐름과 평가 설정은 서버의
                  manager.py에서 결정됩니다.
                </S.Note>
              </>
            ) : (
              <>
                <S.Title>실행할 질문 파일을 선택하세요</S.Title>
                <S.Description>
                  {inputMode === 'custom' ? '직접 준비한 질문' : '미리 생성한 질문'} 목록입니다. 선택한 파일의 모든
                  질문에 동일한 RAG 흐름을 실행합니다.
                </S.Description>
                <S.ListHeader>
                  <span>
                    {fileStatus === 'ready'
                      ? `사용 가능한 파일 ${serverFiles.length}개`
                      : fileStatus === 'loading'
                        ? '서버에서 파일 목록을 불러오는 중'
                        : '파일 목록을 확인하지 못했습니다'}
                  </span>
                  <S.RefreshButton type="button" onClick={handleRefresh}>
                    <RefreshCw size={13} />
                    새로고침
                  </S.RefreshButton>
                </S.ListHeader>
                {fileStatus === 'loading' ? (
                  <S.Empty role="status">
                    <RefreshCw size={24} />
                    <strong>파일 목록을 불러오고 있습니다</strong>서버 응답을 기다려 주세요.
                  </S.Empty>
                ) : fileStatus === 'error' ? (
                  <S.Empty>
                    <FolderOpen size={26} />
                    <strong>파일 목록을 불러오지 못했습니다</strong>서버 연결을 확인한 뒤 새로고침하세요.
                  </S.Empty>
                ) : serverFiles.length ? (
                  <S.Fieldset>
                    <legend>평가할 파일 · 한 개 선택</legend>
                    <S.FileListContainer>
                      {serverFiles.map((file) => (
                        <S.FileToggleItem key={file} $selected={file === selectedFileName}>
                          <input
                            type="radio"
                            name="query-file"
                            aria-label={file}
                            value={file}
                            checked={file === selectedFileName}
                            onChange={() => setSelectedFileName(file)}
                          />
                          <FileText size={18} />
                          <span>{file}</span>
                          {file === selectedFileName && <small aria-hidden="true">선택됨</small>}
                        </S.FileToggleItem>
                      ))}
                    </S.FileListContainer>
                  </S.Fieldset>
                ) : (
                  <S.Empty>
                    <FolderOpen size={26} />
                    <strong>아직 질문 파일이 없습니다</strong>
                    {inputMode === 'custom' ? (
                      <>프로젝트의 datas/queries/custom 폴더에 질문을 한 줄에 하나씩 저장한 .txt 파일을 준비하세요.</>
                    ) : (
                      <>query-gen을 실행해 datas/queries/generated에 질문 파일을 만든 뒤 새로고침하세요.</>
                    )}
                  </S.Empty>
                )}
              </>
            )}
            <S.ButtonWrapper>
              {step > 1 ? (
                <S.BackButton type="button" onClick={handlePrevStep}>
                  <ArrowLeft size={15} />
                  소스 바꾸기
                </S.BackButton>
              ) : (
                <S.RunSummary>파일을 선택한 뒤 실행 여부를 결정합니다.</S.RunSummary>
              )}
              <S.SubmitButton type="button" onClick={handleNextStep} disabled={step === 2 && !validSelection}>
                {step === 2 ? <Play size={15} /> : <ArrowRight size={15} />}
                {step === 2 ? '선택한 파일로 평가 실행' : '파일 선택하기'}
              </S.SubmitButton>
            </S.ButtonWrapper>
            {step === 2 && validSelection && (
              <S.Note>
                선택한 파일: <strong style={{ color: 'var(--text)' }}>{selectedFileName}</strong>
                <br />
                완료 후 대시보드로 이동합니다. 원래 지표 단위와 ‘평가 안 됨’ 상태를 함께 확인하세요.
              </S.Note>
            )}
          </>
        )}
      </S.FormContainer>
    </S.SettingsContainer>
  );
};
