import React, { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { activateDialog } from '../Dashboard/MetricDialog';
import * as S from './TestQuery.styled';

/** Portal mounting replaces the trigger DOM node; restore the current normal-view control. */
export function activateGraphDialog(
  dialog: HTMLElement,
  onClose: () => void,
  returnControl: () => HTMLElement | null,
  doc: Document = document,
) {
  const cleanup = activateDialog(dialog, onClose, doc);
  return () => {
    cleanup();
    const control = returnControl();
    if (control?.isConnected) control.focus();
  };
}

export function GraphDialog({
  id,
  titleId,
  descriptionId,
  onClose,
  returnFocusRef,
  children,
}: {
  id: string;
  titleId: string;
  descriptionId: string;
  onClose: () => void;
  returnFocusRef: React.RefObject<HTMLButtonElement>;
  children: React.ReactNode;
}) {
  const ref = useRef<HTMLElement>(null);
  const close = useRef(onClose);
  close.current = onClose;
  useEffect(
    () =>
      ref.current
        ? activateGraphDialog(
            ref.current,
            () => close.current(),
            () => returnFocusRef.current,
          )
        : undefined,
    [],
  );
  const dialog = (
    <S.GraphOverlay
      onClick={(event) => {
        if (event.target === event.currentTarget) close.current();
      }}
    >
      <S.FlowPanel
        $expanded
        ref={ref}
        id={id}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={descriptionId}
        tabIndex={-1}
      >
        {children}
      </S.FlowPanel>
    </S.GraphOverlay>
  );
  return typeof document === 'undefined' ? dialog : createPortal(dialog, document.body);
}
