import React from 'react';
import styled from 'styled-components';

function format(value: unknown): string {
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value, null, 2) ?? '미기록';
  } catch {
    return '표시할 수 없는 메타데이터';
  }
}
const Details = styled.details`
  margin-top: 10px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.65;
  overflow-wrap: anywhere;
  summary {
    width: fit-content;
    padding: 4px 0;
    cursor: pointer;
    font-weight: 500;
    color: var(--muted);
  }
  summary:hover {
    color: var(--accent);
  }
  @media (max-width: 640px) {
    summary {
      min-height: 44px;
      padding: 10px 0;
    }
  }
  dl {
    margin: 8px 0 0;
    padding: 12px 14px;
    border-radius: 9px;
    background: var(--surface-soft);
  }
  dt {
    color: var(--text);
    font-weight: 600;
  }
  dd {
    margin: 2px 0 12px;
    white-space: pre-wrap;
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
    font-size: 11px;
  }
  dl > div:last-child dd {
    margin-bottom: 0;
  }
`;
/** Raw identifiers remain available without occupying the primary reading flow. */
export function TechnicalDetails({ entries }: { entries: [string, unknown][] }) {
  const present = entries.filter(([, value]) => value !== undefined && value !== null && value !== '');
  if (!present.length) return null;
  return (
    <Details data-technical-details>
      <summary>기술 정보</summary>
      <dl>
        {present.map(([label, value]) => (
          <div key={label}>
            <dt>{label}</dt>
            <dd>{format(value)}</dd>
          </div>
        ))}
      </dl>
    </Details>
  );
}
