import React, { useEffect, useRef, useId } from 'react';
import { createPortal } from 'react-dom';
import { X } from 'lucide-react';
import * as S from './Dashboard.styled';

const FOCUSABLE =
  'button:not([disabled]), select:not([disabled]), input:not([disabled]), textarea:not([disabled]), a[href], summary, [tabindex]:not([tabindex="-1"])';

/** Installs keyboard containment and restores the invoking control on close. */
export function activateDialog(dialog: HTMLElement, onClose: () => void, doc: Document = document) {
  const previous = doc.activeElement as HTMLElement | null;
  const previousOverflow = doc.body.style.overflow;
  const siblings = Array.from(doc.body.children).filter((element) => !element.contains(dialog));
  const inertBefore = siblings.map((element) => [element, element.hasAttribute('inert')] as const);
  siblings.forEach((element) => element.setAttribute('inert', ''));
  const focusable = () =>
    Array.from(dialog.querySelectorAll<HTMLElement>(FOCUSABLE)).filter((el) => {
      // Controls inside a collapsed evidence disclosure are not keyboard targets.
      let parent = el.parentElement;
      while (parent && parent !== dialog) {
        if (parent.tagName === 'DETAILS' && !(parent as HTMLDetailsElement).open && parent.firstElementChild !== el)
          return false;
        parent = parent.parentElement;
      }
      return !el.hidden && el.getAttribute('aria-hidden') !== 'true';
    });
  const focusFirst = () => (focusable()[0] || dialog).focus();
  const onKeyDown = (event: KeyboardEvent) => {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      onClose();
    } else if (event.key === 'Tab') {
      const targets = focusable(),
        first = targets[0],
        last = targets.at(-1);
      if (!first) {
        event.preventDefault();
        dialog.focus();
      } else if (event.shiftKey && (doc.activeElement === first || !dialog.contains(doc.activeElement))) {
        event.preventDefault();
        last?.focus();
      } else if (!event.shiftKey && (doc.activeElement === last || !dialog.contains(doc.activeElement))) {
        event.preventDefault();
        first.focus();
      }
    }
  };
  const onFocus = (event: FocusEvent) => {
    if (!dialog.contains(event.target as Node)) focusFirst();
  };
  doc.body.style.overflow = 'hidden';
  doc.addEventListener('keydown', onKeyDown);
  doc.addEventListener('focusin', onFocus);
  focusFirst();
  return () => {
    doc.removeEventListener('keydown', onKeyDown);
    doc.removeEventListener('focusin', onFocus);
    doc.body.style.overflow = previousOverflow;
    inertBefore.forEach(([element, hadInert]) => {
      if (!hadInert) element.removeAttribute('inert');
    });
    if (previous?.isConnected) previous.focus();
  };
}

export function MetricDialog({
  title,
  description,
  onClose,
  children,
}: {
  title: string;
  description: string;
  onClose: () => void;
  children: React.ReactNode;
}) {
  const ref = useRef<HTMLDivElement>(null),
    close = useRef(onClose),
    id = useId();
  close.current = onClose;
  useEffect(() => (ref.current ? activateDialog(ref.current, () => close.current()) : undefined), []);
  const dialog = (
    <S.ModalOverlay
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <S.DialogPanel
        ref={ref}
        role="dialog"
        aria-modal="true"
        aria-labelledby={`${id}-title`}
        aria-describedby={`${id}-description`}
        tabIndex={-1}
      >
        <S.BoxHeader>
          <div>
            <S.BoxTitle id={`${id}-title`}>{title}</S.BoxTitle>
            <S.QueryInfoText id={`${id}-description`}>{description}</S.QueryInfoText>
          </div>
          <S.IconButton aria-label="상세 닫기" onClick={onClose}>
            <X size={18} />
          </S.IconButton>
        </S.BoxHeader>
        {children}
      </S.DialogPanel>
    </S.ModalOverlay>
  );
  return typeof document === 'undefined' ? dialog : createPortal(dialog, document.body);
}
