import React from 'react';
import { Link } from 'react-router-dom';
import { MessageSquare, Files } from 'lucide-react';
import * as S from './Dashboard.styled';

export function DashboardEmptyState({ loaded }: { loaded: boolean }) {
  return (
    <S.ChartBox>
      <S.BoxTitleH3>{loaded ? '첫 평가 실행을 시작하세요' : '실행 이력을 불러오고 있습니다'}</S.BoxTitleH3>
      <S.QueryInfoText>
        {loaded
          ? '저장된 실행이 없습니다. 실시간 검증에서 질문 하나를 실행하거나, 질문 파일로 여러 질문을 한 번에 평가하세요.'
          : '로컬 서버가 실행 중인지 확인하세요. 연결을 다시 시도하려면 위의 새로고침을 누르세요.'}
      </S.QueryInfoText>
      <S.EmptyActions>
        <S.TextButton as={Link} to="/test">
          <MessageSquare size={15} />
          실시간 검증 열기
        </S.TextButton>
        <S.TextButton as={Link} to="/run-queries">
          <Files size={15} />
          질문 파일 평가
        </S.TextButton>
      </S.EmptyActions>
    </S.ChartBox>
  );
}
