import React, { useRef, useEffect, useMemo, useState, useCallback, useId } from 'react';
import * as S from './TestQuery.styled';
import { GraphDialog } from './GraphDialog';
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { CHART_COLORS } from '../../globals/styles/color';
import { CheckCircle2, Circle, AlertCircle, Maximize2, Minimize2, Scan, RotateCcw, Send } from 'lucide-react';
import { Accordion } from '../../components/Accordion';
import { LiveMetric } from '../../globals/recoil/atoms';
import { MetricScore } from '../../globals/types';
import { MetricDetails } from '../../components/MetricDetails';
import { TechnicalDetails } from '../../components/TechnicalDetails';
import { metricDisplayCatalog, moduleDisplayName, liveSeriesDisplayNames } from '../../utils/display';
import { metricIdentity } from '../Dashboard/analysis';
import { GRAPH_NODE_WIDTH, GRAPH_NODE_HEIGHT, GRAPH_FIT_VIEW_OPTIONS, feedbackPath } from './graph';
import { LiveQueryDetail } from './liveData';
import { liveSeriesDomain } from './chartDomain';
import ReactFlow, {
  Controls,
  Background,
  Handle,
  Position,
  Node,
  Edge,
  OnNodesChange,
  OnEdgesChange,
  ReactFlowInstance,
  EdgeProps,
  BaseEdge,
  EdgeLabelRenderer,
} from 'reactflow';
import 'reactflow/dist/style.css';

const formatScore = (metric: MetricScore & { score: number }): string =>
  `${metric.score.toPrecision(4)}${metric.unit ? ` ${metric.unit}` : ''}`;

export const moduleStatusText = (status: string) =>
  (
    ({
      pending: '대기',
      loading: '실행 중',
      start: '실행 중',
      completed: '완료',
      end: '완료',
      failed: '실패',
      unknown: '상태 미기록',
    }) as Record<string, string>
  )[status] || '대기';

export const ModuleNode = ({ data }: { data: { label: string; status: string; repetitions?: number } }) => {
  const loading = data.status === 'loading' || data.status === 'start';
  const complete = data.status === 'completed' || data.status === 'end';
  const failed = data.status === 'failed';
  const color = failed ? '#b42338' : loading ? '#4f46e5' : complete ? '#087f70' : '#52617a';
  return (
    <div
      style={{
        width: GRAPH_NODE_WIDTH,
        height: GRAPH_NODE_HEIGHT,
        boxSizing: 'border-box',
        borderRadius: 12,
        border: `1px solid ${failed || loading || complete ? color : '#dce3ee'}`,
        background: failed ? '#fff0f2' : '#fff',
        boxShadow: loading ? '0 3px 16px #4f46e51c' : '0 2px 7px #17243b08',
        padding: '12px 14px',
        color: '#17243b',
        textAlign: 'left',
        pointerEvents: 'all',
      }}
      aria-label={`${data.label} · ${moduleStatusText(data.status)}${data.repetitions ? ` · ${data.repetitions}회 실행` : ''}`}
    >
      <Handle type="target" id="in" position={Position.Top} style={{ background: '#a1aec2', width: 7, height: 7 }} />
      <Handle
        type="target"
        id="feedback-in"
        position={Position.Left}
        style={{ top: '38%', background: '#b16a1b', width: 6, height: 6 }}
      />
      <div
        title={data.label}
        className="nowheel nodrag nopan"
        style={{
          fontSize: 16,
          fontWeight: 700,
          lineHeight: '18px',
          overflowWrap: 'anywhere',
          height: 36,
          overflowY: 'auto',
        }}
      >
        {data.label}
      </div>
      <div
        style={{ display: 'flex', alignItems: 'center', gap: 6, color, fontSize: 12, lineHeight: '14px', marginTop: 4 }}
      >
        {loading ? (
          <S.Spinner />
        ) : failed ? (
          <AlertCircle size={13} />
        ) : complete ? (
          <CheckCircle2 size={13} />
        ) : (
          <Circle size={12} />
        )}
        <span>{moduleStatusText(data.status)}</span>
        {!!data.repetitions && <span style={{ marginLeft: 'auto', color: '#52617a' }}>{data.repetitions}회 실행</span>}
      </div>
      <Handle
        type="source"
        id="out"
        position={Position.Bottom}
        style={{ background: '#a1aec2', width: 7, height: 7 }}
      />
      <Handle
        type="source"
        id="feedback-out"
        position={Position.Left}
        style={{ top: '62%', background: '#b16a1b', width: 6, height: 6 }}
      />
    </div>
  );
};

const FeedbackEdge = ({ sourceX, sourceY, targetX, targetY, markerEnd, style, data }: EdgeProps) => {
  const route = feedbackPath(sourceX, sourceY, targetX, targetY, data?.laneX ?? 20);
  return (
    <>
      <BaseEdge path={route.path} markerEnd={markerEnd} style={style} />
      <EdgeLabelRenderer>
        <span
          style={{
            position: 'absolute',
            transform: `translate(-50%, -50%) translate(${route.labelX}px,${route.labelY}px)`,
            background: '#fff8ee',
            color: '#935319',
            border: '1px solid #f0d6af',
            borderRadius: 5,
            padding: '3px 6px',
            fontSize: 10,
            pointerEvents: 'none',
          }}
        >
          순환 연결
        </span>
      </EdgeLabelRenderer>
    </>
  );
};
const nodeTypes = { moduleNode: ModuleNode };
const edgeTypes = { feedback: FeedbackEdge };

const CustomTooltip = ({ active, payload, seriesLabels }: any) =>
  active && payload?.length ? (
    <div
      style={{
        background: '#fff',
        border: '1px solid #dce3ee',
        padding: 12,
        borderRadius: 8,
        fontSize: 12,
        color: '#17243b',
        maxWidth: 320,
      }}
    >
      <p style={{ marginBottom: 6, overflowWrap: 'anywhere' }}>질문: {payload[0].payload.query}</p>
      {payload.map((item: any) => (
        <p key={item.dataKey} style={{ color: item.color }}>
          {seriesLabels[item.dataKey] || '지표'}:{' '}
          {typeof item.value === 'number' ? item.value.toPrecision(4) : item.value}
        </p>
      ))}
    </div>
  ) : null;

interface TestQueryViewProps {
  moduleLabels: Record<string, string>;
  nodes: Node[];
  edges: Edge[];
  graphBounds: { x: number; y: number; width: number; height: number };
  onNodesChange: OnNodesChange;
  onEdgesChange: OnEdgesChange;
  messages: { sender: 'user' | 'bot'; text: string }[];
  metrics: { moduleName: string; metrics: MetricScore[]; queryId?: string; query?: string }[];
  liveMetricsHistory: LiveMetric[];
  selectedQuery?: LiveQueryDetail;
  activeQuery: string;
  handleSendMessage: (e: React.FormEvent<HTMLFormElement>) => void;
  handleReset: () => void;
}

export const TestQueryView: React.FC<TestQueryViewProps> = ({
  nodes,
  moduleLabels,
  edges,
  graphBounds,
  onNodesChange,
  onEdgesChange,
  messages,
  handleSendMessage,
  metrics,
  liveMetricsHistory,
  selectedQuery,
  activeQuery,
  handleReset,
}) => {
  const messageAreaRef = useRef<HTMLDivElement>(null);
  const graphAreaRef = useRef<HTMLDivElement>(null);
  const expandButtonRef = useRef<HTMLButtonElement>(null);
  const graphId = useId();
  const [expanded, setExpanded] = useState(false);
  const [flow, setFlow] = useState<ReactFlowInstance | null>(null);
  const metricCatalog = useRef(metricDisplayCatalog);
  const metricLabels = useMemo(
    () => metricCatalog.current.labelsFor(metrics.flatMap((group) => group.metrics)),
    [metrics],
  );
  const metricText = (identity: string) => metricLabels[identity] || '지표';
  const moduleText = (id: string) => moduleLabels[id] || moduleDisplayName(id);
  const seriesLabels = liveSeriesDisplayNames(metrics, metricLabels, moduleLabels);
  const selectedMetrics = activeQuery ? metrics.filter((group) => group.queryId === activeQuery) : [];
  const fitGraph = useCallback(() => {
    if (flow) flow.fitBounds(graphBounds, { padding: GRAPH_FIT_VIEW_OPTIONS.padding, duration: 180 });
  }, [flow, graphBounds]);
  useEffect(() => {
    if (messageAreaRef.current) messageAreaRef.current.scrollTop = messageAreaRef.current.scrollHeight;
  }, [messages]);
  useEffect(() => {
    const timer = setTimeout(fitGraph, 40);
    const observer = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(fitGraph) : null;
    if (graphAreaRef.current) observer?.observe(graphAreaRef.current);
    return () => {
      clearTimeout(timer);
      observer?.disconnect();
    };
  }, [fitGraph, expanded]);

  const moduleMetrics = useMemo(() => {
    const grouped: Record<string, Record<string, number[]>> = {};
    metrics.forEach((group) =>
      group.metrics.forEach((metric) => {
        if (!metric.didEval || metric.score === null) return;
        const values = (grouped[group.moduleName] ||= {});
        (values[metricIdentity(metric)] ||= []).push(metric.score);
      }),
    );
    return Object.entries(grouped).map(([moduleName, values]) => ({
      moduleName,
      metrics: Object.entries(values).map(([name, scores]) => {
        const minimum = Math.min(...scores),
          maximum = Math.max(...scores);
        const distribution =
          minimum === maximum
            ? [{ range: minimum.toPrecision(4), count: scores.length }]
            : Array.from({ length: 10 }, (_, index) => {
                const width = (maximum - minimum) / 10,
                  start = minimum + index * width,
                  end = index === 9 ? maximum : minimum + (index + 1) * width;
                return {
                  range: `${start.toPrecision(3)}–${end.toPrecision(3)}`,
                  count: scores.filter((score) => score >= start && (index === 9 ? score <= end : score < end)).length,
                };
              });
        return { name, distribution };
      }),
    }));
  }, [metrics]);
  const availableMetrics = Array.from(
    new Set(
      (liveMetricsHistory || []).flatMap((row) =>
        Object.keys(row).filter((key) => !['query', 'queryNumber', 'queryId'].includes(key)),
      ),
    ),
  );

  const flowContent = (
    <>
      <S.TestQueryHeader>
        <div>
          <S.Title id={`${graphId}-title`}>모듈 흐름</S.Title>
          <S.Description id={`${graphId}-description`}>
            화살표는 선언된 연결입니다. 위에서 아래로 흐름을 읽고, 점선은 구조적으로 되돌아가는 순환 연결입니다.
          </S.Description>
        </div>
        <S.ButtonGroup>
          <S.ResetButton onClick={fitGraph}>
            <Scan size={14} />
            전체 보기
          </S.ResetButton>
          <S.ResetButton
            ref={expandButtonRef}
            onClick={() => setExpanded(!expanded)}
            aria-haspopup="dialog"
            aria-expanded={expanded}
            aria-controls={expanded ? graphId : undefined}
            aria-label={expanded ? '그래프 크게 보기 닫기' : '그래프 크게 보기'}
          >
            {expanded ? <Minimize2 size={14} /> : <Maximize2 size={14} />}
            {expanded ? '화면 복원' : '크게 보기'}
          </S.ResetButton>
          <S.ResetButton onClick={handleReset}>
            <RotateCcw size={14} />
            기록 초기화
          </S.ResetButton>
        </S.ButtonGroup>
      </S.TestQueryHeader>
      <S.Legend>
        <span>
          <i style={{ background: '#a1aec2' }} />
          대기
        </span>
        <span>
          <i style={{ background: '#4f46e5' }} />
          실행 중
        </span>
        <span>
          <i style={{ background: '#087f70' }} />
          완료
        </span>
        <span>
          <i style={{ background: '#b42338' }} />
          실패
        </span>
        <span style={{ color: '#935319' }}>┄ 순환 연결 · 재시도 의미는 모듈 계약에 따라 확인</span>
      </S.Legend>
      <S.GraphCanvas ref={graphAreaRef} $expanded={expanded}>
        {nodes.length ? (
          <ReactFlow
            nodes={nodes}
            edges={edges}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            nodeTypes={nodeTypes}
            edgeTypes={edgeTypes}
            onInit={setFlow}
            minZoom={GRAPH_FIT_VIEW_OPTIONS.minZoom}
            maxZoom={1.8}
            nodesConnectable={false}
            elementsSelectable={false}
            proOptions={{ hideAttribution: true }}
          >
            <Background color="#dce3ee" gap={22} size={1} />
            <Controls showInteractive={false} showFitView={false} />
          </ReactFlow>
        ) : (
          <S.Empty>
            <strong>흐름 정보를 기다리고 있습니다</strong>서버 연결 후 선언된 모듈과 연결이 표시됩니다.
          </S.Empty>
        )}
      </S.GraphCanvas>
      <S.Description style={{ margin: '10px 0 0' }}>
        스크롤로 확대 · 드래그로 이동 · 전체 보기로 화면 맞춤. 노드의 횟수는 선택한 질문에서 관측한 실행 수입니다.
      </S.Description>
    </>
  );

  return (
    <S.PageLayout>
      {expanded ? (
        <GraphDialog
          id={graphId}
          titleId={`${graphId}-title`}
          descriptionId={`${graphId}-description`}
          onClose={() => setExpanded(false)}
          returnFocusRef={expandButtonRef}
        >
          {flowContent}
        </GraphDialog>
      ) : (
        <S.FlowPanel aria-label="선언된 모듈 흐름">{flowContent}</S.FlowPanel>
      )}

      <S.ChatPanel>
        <S.Title>질문과 답변</S.Title>
        <S.Description>
          질문 하나를 보내 실제 RAG 흐름을 실행하세요. 아래 대화는 이 화면에서 받은 전체 기록입니다.
        </S.Description>
        <S.MessageArea ref={messageAreaRef} aria-live="polite">
          {!messages.length && (
            <S.Empty>
              <strong>첫 질문으로 흐름을 확인하세요</strong>예: “배포 실패 시 어떤 절차로 복구하나요?”
            </S.Empty>
          )}
          {messages.map((message, index) => (
            <S.MessageWrapper key={index} sender={message.sender}>
              <S.MessageLabel>{message.sender === 'user' ? '내 질문' : 'RAG 응답'}</S.MessageLabel>
              <S.MessageBubble sender={message.sender}>{message.text}</S.MessageBubble>
            </S.MessageWrapper>
          ))}
        </S.MessageArea>
        <S.InputForm onSubmit={handleSendMessage}>
          <S.StyledInput
            aria-label="실행할 질문"
            name="queryInput"
            type="text"
            placeholder="확인할 질문을 입력하세요"
            required
          />
          <S.SendButton type="submit">
            <Send size={14} aria-hidden="true" /> 실행
          </S.SendButton>
        </S.InputForm>
      </S.ChatPanel>

      <S.ResultPanel>
        <S.Title>선택한 질문의 평가</S.Title>
        <S.Description>
          반복 실행의 각 회차를 보존합니다. 점수는 지표가 선언한 단위를 유지하며, 평가되지 않은 결과는 수치로 대체하지
          않습니다.
        </S.Description>
        <S.ScrollableContent>
          {!selectedMetrics.length && (
            <S.Empty>
              <strong>아직 평가 지표가 없습니다</strong>실행 후 지표가 설정된 모듈의 결과가 표시됩니다. 모듈 실행 상태는
              그래프와 아래 실행 순서에서 확인하세요.
            </S.Empty>
          )}
          {selectedMetrics.map((group, index) => {
            const evaluated = group.metrics.filter((metric) => metric.didEval && metric.score !== null).length;
            return (
              <Accordion
                key={`${group.queryId}-${group.moduleName}-${index}`}
                title={
                  <div style={{ minWidth: 0 }}>
                    <div style={{ fontSize: 13, color: 'var(--text)', overflowWrap: 'anywhere' }}>
                      {moduleText(group.moduleName)}
                    </div>
                    <small style={{ color: 'var(--muted)', fontSize: 11 }}>
                      {evaluated}/{group.metrics.length}개 평가 완료
                    </small>
                  </div>
                }
              >
                <TechnicalDetails
                  entries={[
                    ['질문 ID', group.queryId],
                    ['모듈 ID', group.moduleName],
                  ]}
                />
                {group.metrics.map((metric, metricIndex) => (
                  <div key={metricIndex}>
                    <S.TableRow>
                      <span>{metricText(metricIdentity(metric))}</span>
                      <span style={{ color: metric.didEval ? 'var(--text)' : 'var(--danger)' }}>
                        {metric.didEval && metric.score !== null
                          ? formatScore(metric as MetricScore & { score: number })
                          : '평가 안 됨'}
                      </span>
                    </S.TableRow>
                    <details style={{ fontSize: 12, color: 'var(--muted)', paddingBottom: 10 }}>
                      <summary style={{ cursor: 'pointer' }}>판정 근거와 평가 범위</summary>
                      <MetricDetails metric={metric} />
                    </details>
                  </div>
                ))}
              </Accordion>
            );
          })}
        </S.ScrollableContent>
        <details style={{ marginTop: 16, fontSize: 12, color: 'var(--muted)' }} open={!!selectedQuery?.outcome}>
          <summary style={{ cursor: 'pointer' }}>
            실제로 실행된 순서 · {selectedQuery ? `${selectedQuery.executions.length}단계` : '기록 미수신'}
          </summary>
          {selectedQuery?.executions.length ? (
            <S.Trace>
              {selectedQuery.executions.map((execution, index) => (
                <li key={execution.id}>
                  <b>{index + 1}단계</b>
                  <span>
                    {moduleText(execution.moduleId)} · {execution.repetition}회차{' '}
                    <small>
                      · {moduleStatusText(execution.status)}
                      {execution.nextModules.length ? ` → ${execution.nextModules.map(moduleText).join(', ')}` : ''}
                    </small>
                  </span>
                </li>
              ))}
            </S.Trace>
          ) : (
            <S.Description>실행 ID가 포함된 이벤트나 저장된 실행 기록을 받은 뒤 표시됩니다.</S.Description>
          )}
        </details>
      </S.ResultPanel>

      <S.LiveScorePanel>
        <S.Title>질문별 지표 변화</S.Title>
        <S.Description>
          전체 수신 기록에서 같은 모듈·회차·평가 설정의 지표만 연결합니다. 값이 없는 질문 구간은 연결하지 않습니다.
        </S.Description>
        {availableMetrics.length ? (
          <div
            style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(min(100%, 340px), 1fr))', gap: 20 }}
          >
            {availableMetrics.map((name, index) => (
              <div key={name}>
                <S.MetricTitle>{seriesLabels[name] || '지표'}</S.MetricTitle>
                <ResponsiveContainer width="100%" height={190}>
                  <LineChart data={liveMetricsHistory} margin={{ top: 8, right: 20, left: 0, bottom: 10 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#dce3ee" />
                    <XAxis
                      dataKey="queryNumber"
                      stroke="#52617a"
                      fontSize={12}
                      label={{ value: '결과 수신 순서', position: 'insideBottom', offset: -5 }}
                    />
                    <YAxis
                      stroke="#52617a"
                      fontSize={12}
                      domain={liveSeriesDomain(name, metrics, liveMetricsHistory)}
                      allowDataOverflow={false}
                    />
                    <Tooltip content={<CustomTooltip seriesLabels={seriesLabels} />} />
                    <Line
                      isAnimationActive={false}
                      type="linear"
                      dataKey={name}
                      name={seriesLabels[name] || '지표'}
                      stroke={CHART_COLORS[index % CHART_COLORS.length]}
                      connectNulls={false}
                    />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            ))}
          </div>
        ) : (
          <S.Empty>평가가 완료된 지표를 받으면 질문별 변화가 표시됩니다.</S.Empty>
        )}
        {!!moduleMetrics.length && (
          <details style={{ marginTop: 16, color: 'var(--muted)', fontSize: 12 }}>
            <summary style={{ cursor: 'pointer' }}>지표별 값 분포 보기</summary>
            <S.ScrollableContent style={{ marginTop: 18 }}>
              {moduleMetrics.map((group) => (
                <S.ModuleSection key={group.moduleName}>
                  <S.ModuleTitle>{moduleText(group.moduleName)}</S.ModuleTitle>
                  <S.MetricsGrid>
                    {group.metrics.map((metric) => (
                      <S.MetricBox key={metric.name}>
                        <S.MetricTitle>{metricText(metric.name)}</S.MetricTitle>
                        <ResponsiveContainer width="100%" height={140}>
                          <BarChart data={metric.distribution}>
                            <CartesianGrid strokeDasharray="3 3" stroke="#dce3ee" />
                            <XAxis
                              dataKey="range"
                              stroke="#52617a"
                              fontSize={12}
                              minTickGap={24}
                              interval="preserveStartEnd"
                              height={44}
                            />
                            <YAxis stroke="#52617a" allowDecimals={false} fontSize={12} />
                            <Tooltip contentStyle={{ backgroundColor: '#fff', borderColor: '#dce3ee', fontSize: 12 }} />
                            <Bar isAnimationActive={false} dataKey="count" name="평가 결과 수" fill="#4f46e5" />
                          </BarChart>
                        </ResponsiveContainer>
                      </S.MetricBox>
                    ))}
                  </S.MetricsGrid>
                </S.ModuleSection>
              ))}
            </S.ScrollableContent>
          </details>
        )}
      </S.LiveScorePanel>
    </S.PageLayout>
  );
};
