import React from 'react';
import { TechnicalDetails } from '../../components/TechnicalDetails';
import { questionDisplayName, moduleDisplayName, terminationDisplayName, traceDisplayRows } from '../../utils/display';
import { MetricDetails } from '../../components/MetricDetails';
import { KPICard } from '../../components/KPICard';
import { MetricDialog } from './MetricDialog';
import type {
  EvaluationRun,
  MetricScore,
  DiagnosticInference,
  DiagnosticObservation,
  EvaluatorHealth,
  ExecutionTraceEvent,
  GraphHealth,
} from '../../globals/types';
import type { Aggregation } from './analysis';
import { metricIdentity } from './analysis';
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  Cell,
} from 'recharts';
import { ArrowUpRight, CheckCircle2, FileSearch, Activity } from 'lucide-react';
import * as S from './Dashboard.styled';
import type { ChartDomain } from '../../utils/chartDomain';

interface DashboardViewProps {
  metricLabels: Record<string, string>;
  moduleLabels: Record<string, string>;
  selectedRunLabel: string;
  baselineRunLabel: string;
  selectedRun?: EvaluationRun;
  baselineRun?: EvaluationRun;
  comparisons: ReturnType<typeof import('./analysis').compareModuleRuns>;
  aggregation: Aggregation;
  notEvaluated: { query: string; queryId?: string; executionIndex?: number; metric: MetricScore }[];
  kpiData: {
    evaluatedMetrics: string;
    notEvaluatedMetrics: string;
    evaluatorCoverage: string;
    traceExecutions: string;
  };
  zoomedMetric: string | null;
  selectedDate: string;
  selectedModule: string;
  zoomedFrequencyData: any[];
  modulePerformanceData: any[];
  handleDotClick: (payload: any) => void;
  handleFrequencyBarClick: (data: any) => void;
  moduleColors: string[];
  detailedQueryData: any[] | undefined;
  selectedScoreRange: [number, number] | null;
  metricDistributionData: any[];
  metricPerformanceBreakdownData: Record<string, any[]>;
  metricChartDomains?: Record<string, ChartDomain>;
  handleZoomClick: (metricName: string) => void;
  handleZoomOut: () => void;
  allModuleNames: string[];
  evaluatorHealth?: EvaluatorHealth;
  diagnosticObservations: DiagnosticObservation[];
  diagnosticInferences: DiagnosticInference[];
  configFingerprint: string | null;
  executionTrace: ExecutionTraceEvent[];
  graphHealth?: GraphHealth;
}

const axis = {
  stroke: '#52617a',
  tick: { fontSize: 12, fill: '#52617a' },
  tickLine: false,
  axisLine: false,
  minTickGap: 20,
};
const tooltipStyle = {
  backgroundColor: '#ffffff',
  borderColor: '#dce3ee',
  borderRadius: 10,
  color: '#17243b',
  fontSize: 13,
  lineHeight: 1.7,
  boxShadow: '0 6px 20px rgba(23,36,59,0.08)',
};
const confidenceLabel = (confidence: string) => ({ high: '높음', medium: '중간', low: '낮음' })[confidence] || '미기록';

export const DashboardView: React.FC<DashboardViewProps> = ({
  kpiData,
  metricLabels,
  moduleLabels,
  selectedRunLabel,
  baselineRunLabel,
  zoomedMetric,
  selectedModule,
  zoomedFrequencyData,
  modulePerformanceData,
  handleDotClick,
  handleFrequencyBarClick,
  moduleColors,
  detailedQueryData,
  selectedScoreRange,
  metricDistributionData,
  handleZoomClick,
  handleZoomOut,
  allModuleNames,
  metricPerformanceBreakdownData,
  metricChartDomains = {},
  diagnosticObservations,
  diagnosticInferences,
  configFingerprint,
  executionTrace,
  graphHealth,
  selectedRun,
  baselineRun,
  comparisons,
  aggregation,
  notEvaluated,
}) => {
  const metricText = (identity: string) => metricLabels[identity] || '지표';
  const moduleText = (id: string) => moduleLabels[id] || moduleDisplayName(id);
  const color = (index: number) => moduleColors[index % moduleColors.length] || '#4f46e5';
  const queryText = (id: string | undefined, text: string) => {
    const index = selectedRun?.queryOutcomes?.findIndex((q) => q.queryId === id) ?? -1;
    return index >= 0 ? questionDisplayName(text, index + 1) : text;
  };
  const traceRows = traceDisplayRows(
    executionTrace,
    moduleLabels,
    selectedRun?.queryOutcomes?.map((query) => query.queryId),
  );
  const pipeline = selectedRun?.pipelineHealth;
  const incompleteQuestions = selectedRun?.queryOutcomes?.filter((q) => q.status !== 'succeeded') || [];
  const aggregationLabel =
    aggregation === 'step' ? '모든 실행 단계' : aggregation === 'query' ? '질문별 실행 평균' : '질문별 마지막 실행';
  const selectedBinIndex = selectedScoreRange
    ? zoomedFrequencyData.findIndex((bin) => bin.start === selectedScoreRange[0] && bin.end === selectedScoreRange[1])
    : -1;
  const chartLines = () =>
    allModuleNames.map((moduleName, index) => (
      <Line
        isAnimationActive={false}
        key={moduleName}
        type="linear"
        dataKey={moduleName}
        name={moduleText(moduleName)}
        stroke={color(index)}
        strokeWidth={2.5}
        dot={{ r: 3 }}
        activeDot={{ r: 5 }}
        connectNulls={false}
      />
    ));
  return (
    <S.DashboardContainer>
      <S.RunSummary aria-label="선택 실행 요약">
        <S.ContextBar>
          <S.RunIdentity>
            <S.Eyebrow>현재 보고 있는 실행</S.Eyebrow>
            <strong>{selectedRunLabel}</strong>
          </S.RunIdentity>
          <S.Badge>
            {moduleText(selectedModule)} · {aggregationLabel}
          </S.Badge>
        </S.ContextBar>
        <p>
          질문 실행 {pipeline?.attempted ?? '미기록'}건 · 성공 {pipeline?.succeeded ?? '미기록'} · 실패{' '}
          {pipeline?.failed ?? '미기록'} · 상태 미기록 {pipeline?.unknown ?? '미기록'}
        </p>
        <S.RunDisclosureRow aria-label="실행 요약 상세 정보">
          <details>
            <summary>집계 기준과 평가 범위 확인</summary>
            <div>
              <p>
                평가 완료 비율은 기록된 평가의 계산 완료 비율입니다. 답변 정확도나 질문 실행 성공률을 뜻하지 않습니다.
              </p>
              <p>
                점수 집계:{' '}
                {aggregation === 'step'
                  ? '실행 단계마다 1표본'
                  : aggregation === 'query'
                    ? '질문별 실행 평균에 동일 가중치'
                    : '질문별 마지막 모듈 실행에 동일 가중치'}
                . 미평가 점수는 평균·분포에서 제외합니다.
              </p>
              {selectedRun?.evaluationPlan && (
                <p>
                  미도달 E2E 평가 {selectedRun.evaluationPlan.notReachedE2E}건 · 실행하지 않은 모듈의 설정 지표{' '}
                  {selectedRun.evaluationPlan.notReachedModuleMetrics}건 (
                  {selectedRun.evaluationPlan.notReachedModules.map(moduleText).join(', ') || '없음'}). 비활성 분기일 수
                  있으므로 미평가 실패와 구분합니다.
                </p>
              )}
              {selectedRun?.timing && (
                <p>
                  모듈 실행 시간 합 {selectedRun.graphHealth.totalLatencySeconds.toFixed(3)}초 · 평가 시간 합{' '}
                  {selectedRun.timing.evaluatorSeconds.toFixed(3)}초 · 질문별 전체 소요 시간 합{' '}
                  {selectedRun.timing.queryWallSecondsSum.toFixed(3)}초. 동시 배치의 실제 경과 시간과는 다릅니다.
                </p>
              )}
            </div>
          </details>
          <TechnicalDetails
            entries={[
              ['실행 ID', selectedRun?.runId],
              ['원본 시각 키', selectedRun?.timestamp],
              ['구성 식별자', configFingerprint],
              ['선택 모듈 ID', selectedModule],
            ]}
          />
        </S.RunDisclosureRow>
      </S.RunSummary>

      <S.KpiCardWrapper aria-label="선택 실행의 평가 지표 요약">
        <KPICard
          title="질문 실행 성공"
          value={pipeline ? String(pipeline.succeeded) : '미기록'}
          description={`전체 질문 ${pipeline?.attempted ?? '미기록'}건 중 완료`}
          tone="success"
        />
        <KPICard
          title="질문 실행 실패"
          value={pipeline ? String(pipeline.failed) : '미기록'}
          description={`상태 미기록 ${pipeline?.unknown ?? '미기록'}건은 별도 집계`}
          tone={pipeline?.failed ? 'danger' : 'neutral'}
        />
        <KPICard
          title="평가 완료"
          value={kpiData.evaluatedMetrics}
          description={`기록된 평가의 완료 비율 ${kpiData.evaluatorCoverage}`}
          tone="accent"
        />
        <KPICard
          title="미평가"
          value={kpiData.notEvaluatedMetrics}
          description="입력 누락·평가 오류 등의 사유 확인"
          tone={Number(kpiData.notEvaluatedMetrics) > 0 ? 'danger' : 'neutral'}
        />
      </S.KpiCardWrapper>

      {incompleteQuestions.length > 0 && (
        <S.Disclosure>
          <summary>완료되지 않은 질문 {incompleteQuestions.length}건 · 종료 사유 확인</summary>
          <div>
            <S.ScrollableContent>
              {incompleteQuestions.map((q) => (
                <S.QueryItem key={q.queryId}>
                  <S.QueryText>{queryText(q.queryId, q.query)}</S.QueryText>
                  <S.Badge $tone={q.status === 'failed' ? 'danger' : 'accent'}>
                    {q.status === 'failed' ? '실행 실패' : '상태 미기록'}
                  </S.Badge>
                  <S.QueryInfoText>종료 이유: {terminationDisplayName(q.reason)}</S.QueryInfoText>
                  <TechnicalDetails
                    entries={[
                      ['질문 ID', q.queryId],
                      ['종료 코드', q.reason],
                    ]}
                  />
                </S.QueryItem>
              ))}
            </S.ScrollableContent>
          </div>
        </S.Disclosure>
      )}

      <S.Section aria-labelledby="metric-results-heading">
        <S.SectionHeading>
          <div>
            <h2 id="metric-results-heading">지표별 점수 분포</h2>
            <p>
              {moduleText(selectedModule)}의 평가 완료 표본입니다. 지표별 원래 단위로 표시하며, 미평가는 포함하지
              않습니다.
            </p>
          </div>
          <S.Badge>
            <CheckCircle2 size={13} />
            {aggregationLabel}
          </S.Badge>
        </S.SectionHeading>
        {metricDistributionData.length ? (
          <S.DistributionGrid>
            {metricDistributionData.map((metric) => (
              <S.ChartBox key={metric.metricName}>
                <S.BoxHeader>
                  <div>
                    <S.BoxTitleH3>{metricText(metric.metricName)}</S.BoxTitleH3>
                    <S.QueryInfoText>
                      평가 완료 표본 {metric.sampleCount ?? metric.data.reduce((n: number, b: any) => n + b.count, 0)}건
                    </S.QueryInfoText>
                  </div>
                  <S.IconButton
                    aria-label={`${metricText(metric.metricName)} 상세 보기`}
                    onClick={() => handleZoomClick(metric.metricName)}
                  >
                    <ArrowUpRight size={18} />
                  </S.IconButton>
                </S.BoxHeader>
                {metric.data.length ? (
                  <S.ChartCanvas $height={210}>
                    <ResponsiveContainer
                      width="100%"
                      height="100%"
                      minWidth={0}
                      initialDimension={{ width: 480, height: 260 }}
                    >
                      <BarChart data={metric.data} margin={{ top: 12, right: 12, left: 0, bottom: 8 }}>
                        <CartesianGrid vertical={false} stroke="#e8edf5" />
                        <XAxis
                          {...axis}
                          dataKey="range"
                          height={42}
                          tick={{ fontSize: 12, fill: '#52617a' }}
                          interval="preserveStartEnd"
                        />
                        <YAxis {...axis} width={38} allowDecimals={false} />
                        <Tooltip contentStyle={tooltipStyle} cursor={{ fill: '#f0f3f9' }} />
                        <Bar
                          isAnimationActive={false}
                          dataKey="count"
                          name={aggregation === 'step' ? '실행 표본 수' : '질문 표본 수'}
                          fill="#4f46e5"
                          radius={[4, 4, 0, 0]}
                          maxBarSize={42}
                        />
                      </BarChart>
                    </ResponsiveContainer>
                  </S.ChartCanvas>
                ) : (
                  <S.NoDataText>
                    평가가 완료된 표본이 없습니다.
                    <br />
                    아래 미평가 기록에서 사유를 확인하세요.
                  </S.NoDataText>
                )}
                <S.TextButton onClick={() => handleZoomClick(metric.metricName)}>
                  질문·답변·평가 근거 보기 <ArrowUpRight size={14} />
                </S.TextButton>
              </S.ChartBox>
            ))}
          </S.DistributionGrid>
        ) : (
          <S.ChartBox>
            <S.NoDataText>
              이 모듈에는 기록된 평가 지표가 없습니다.
              <br />
              다른 모듈을 선택하거나 평가 설정을 확인하세요.
            </S.NoDataText>
          </S.ChartBox>
        )}
      </S.Section>

      {baselineRun && (
        <S.Section aria-labelledby="comparison-heading">
          <S.SectionHeading>
            <div>
              <h2 id="comparison-heading">실행 간 지표 비교</h2>
              <p>동일 질문의 마지막 실행을 비교합니다. 양수·음수의 의미는 각 지표 방향에 따라 다릅니다.</p>
            </div>
          </S.SectionHeading>
          <S.ChartBox>
            <S.QueryInfoText>
              <strong>기준</strong> {baselineRunLabel}
              <br />
              <strong>선택</strong> {selectedRunLabel} · {moduleText(selectedModule)}
            </S.QueryInfoText>
            <S.QueryInfoText>
              판정자·버전·설정이 같고 양쪽 평가가 완료된 질문만 평균과 차이에 포함합니다. 위의 점수 집계 선택과 관계없이
              마지막 실행을 사용합니다.
            </S.QueryInfoText>
            {comparisons.length ? (
              <S.TableScroll>
                <table>
                  <caption style={{ position: 'absolute', width: 1, height: 1, overflow: 'hidden' }}>
                    동일 질문·동일 평가 조건의 지표 비교
                  </caption>
                  <thead>
                    <tr>
                      <th scope="col">지표 · 평가 조건</th>
                      <th scope="col">공통 질문 / 양쪽 평가 완료</th>
                      <th scope="col">기준 평균</th>
                      <th scope="col">선택 평균</th>
                      <th scope="col">차이</th>
                    </tr>
                  </thead>
                  <tbody>
                    {comparisons.map((row) => (
                      <tr key={row.identity}>
                        <td>
                          {metricText(row.identity)}
                          <TechnicalDetails entries={[['지표 내부 식별자', row.identity]]} />
                          {!row.evaluatorVerified && <small>판정자 동일성 미확인 · 비교 불가</small>}
                        </td>
                        <td>
                          {row.pairedQueries} / {row.evaluatedPairs}
                          <small>
                            기준 {row.baselineQueries}, 선택 {row.candidateQueries}, 짝 없는 질문 {row.unmatchedQueries}
                          </small>
                          <small>
                            양쪽 모듈 기록 {row.pairedModuleRecords}, 한쪽 이상 모듈 미도달 {row.missingModulePairs}
                          </small>
                        </td>
                        <S.NumericCell>{row.baselineMean?.toPrecision(4) ?? '미평가'}</S.NumericCell>
                        <S.NumericCell>{row.candidateMean?.toPrecision(4) ?? '미평가'}</S.NumericCell>
                        <S.NumericCell>{row.delta?.toPrecision(4) ?? '비교 불가'}</S.NumericCell>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </S.TableScroll>
            ) : (
              <S.NoDataText>선택한 모듈에서 비교할 지표가 없습니다. 비교 실행이나 모듈을 바꿔보세요.</S.NoDataText>
            )}
          </S.ChartBox>
        </S.Section>
      )}

      {notEvaluated.length > 0 && (
        <S.Disclosure>
          <summary>미평가 사유 살펴보기 · 선택 모듈 {notEvaluated.length}건</summary>
          <div>
            <S.QueryInfoText>
              숫자 0은 유효한 평가값입니다. 아래 기록은 계산 결과가 없어 점수 분포·평균에서 제외되었습니다.
            </S.QueryInfoText>
            <S.ScrollableContent style={{ marginTop: 12 }}>
              {notEvaluated.map((item, i) => (
                <S.QueryItem key={i}>
                  <S.QueryText>
                    {queryText(item.queryId, item.query)} · {metricText(metricIdentity(item.metric))}
                  </S.QueryText>
                  <TechnicalDetails entries={[['질문 ID', item.queryId]]} />
                  <MetricDetails metric={item.metric} />
                </S.QueryItem>
              ))}
            </S.ScrollableContent>
          </div>
        </S.Disclosure>
      )}

      <S.Section aria-labelledby="diagnostics-heading">
        <S.SectionHeading>
          <div>
            <h2 id="diagnostics-heading">무엇을 확인해야 할까요?</h2>
            <p>실행에 남은 관측 기록을 먼저 읽고, 추정 원인을 다음 확인 항목으로 활용하세요.</p>
          </div>
        </S.SectionHeading>
        <S.GridContainer>
          <S.ChartBox>
            <S.BoxHeader>
              <S.BoxTitleH3>
                <FileSearch size={16} style={{ verticalAlign: 'middle', marginRight: 7 }} />
                관측된 근거
              </S.BoxTitleH3>
              <S.Badge $tone="success">기록 {diagnosticObservations.length}건</S.Badge>
            </S.BoxHeader>
            <S.QueryInfoText>실행 기록에서 확인한 사실입니다.</S.QueryInfoText>
            <S.ScrollableContent>
              {diagnosticObservations.length ? (
                diagnosticObservations.map((observation, index) => (
                  <S.QueryItem key={`${observation.code}-${index}`}>
                    <S.QueryText>{observation.message}</S.QueryText>
                    {(observation.query || observation.module || observation.metric) && (
                      <S.QueryInfoText>
                        {[
                          observation.query,
                          observation.module ? moduleText(observation.module) : '',
                          observation.metric,
                        ]
                          .filter(Boolean)
                          .join(' · ')}
                      </S.QueryInfoText>
                    )}
                    <TechnicalDetails
                      entries={[
                        ['관측 코드', observation.code],
                        ['단계 구분', observation.stage],
                        ['모듈 ID', observation.module],
                        ['실패 유형', observation.failureType],
                      ]}
                    />
                  </S.QueryItem>
                ))
              ) : (
                <S.NoDataText>
                  이 실행에는 별도 관측 기록이 없습니다.
                  <br />
                  지표 상세에서 질문과 평가 근거를 확인할 수 있습니다.
                </S.NoDataText>
              )}
            </S.ScrollableContent>
          </S.ChartBox>
          <S.ChartBox>
            <S.BoxHeader>
              <S.BoxTitleH3>추정 원인과 다음 확인</S.BoxTitleH3>
              <S.Badge>가설</S.Badge>
            </S.BoxHeader>
            <S.QueryInfoText>규칙에서 도출한 가설입니다. 확인된 원인이나 검증된 확률이 아닙니다.</S.QueryInfoText>
            <S.ScrollableContent>
              {diagnosticInferences.length ? (
                diagnosticInferences.map((inference, index) => (
                  <S.QueryItem key={`${inference.code}-${index}`}>
                    <S.QueryText>{inference.possibleCause}</S.QueryText>
                    {inference.query && <S.QueryInfoText>{inference.query}</S.QueryInfoText>}
                    <S.QueryInfoText>규칙 기반 신뢰 수준: {confidenceLabel(inference.confidence)}</S.QueryInfoText>
                    <S.QueryInfoText>
                      <strong>다음 확인</strong> · {inference.nextAction}
                    </S.QueryInfoText>
                    <TechnicalDetails entries={[['추정 코드', inference.code]]} />
                  </S.QueryItem>
                ))
              ) : (
                <S.NoDataText>
                  생성된 추정 원인이 없습니다.
                  <br />
                  문제가 없다는 뜻은 아니며, 관측 근거와 미평가 사유를 함께 확인하세요.
                </S.NoDataText>
              )}
            </S.ScrollableContent>
          </S.ChartBox>
        </S.GridContainer>
      </S.Section>

      <S.Disclosure>
        <summary>
          <Activity size={15} style={{ verticalAlign: 'middle', marginRight: 7 }} />
          실행 단계 추적 · {graphHealth?.totalExecutions ?? kpiData.traceExecutions}회 실행 · 실패{' '}
          {graphHealth?.failedExecutions ?? 0}회 · 재방문 {graphHealth?.moduleRevisits ?? 0}회
        </summary>
        <div>
          <S.QueryInfoText>
            실제 실행 순서와 부모 단계를 보존합니다. 종료된 질문 {graphHealth?.terminatedQueries ?? 0}건.
          </S.QueryInfoText>
          <S.ScrollableContent style={{ marginTop: 12, maxHeight: 420 }}>
            {traceRows.length ? (
              traceRows.map(
                ({ event, questionLabel, stepLabel, moduleLabel, parentLabels, nextLabels, statusLabel }) => (
                  <S.QueryItem key={`${event.queryId}-${event.executionId}`}>
                    <S.BoxHeader>
                      <S.QueryText>
                        {questionLabel} · {moduleLabel}
                      </S.QueryText>
                      <S.Badge
                        $tone={
                          event.status === 'failed' ? 'danger' : event.status === 'completed' ? 'success' : 'accent'
                        }
                      >
                        {statusLabel}
                      </S.Badge>
                    </S.BoxHeader>
                    <S.QueryInfoText>
                      {stepLabel} · 이전: {parentLabels.join(', ') || '시작'} · 다음: {nextLabels.join(', ') || '종료'}
                    </S.QueryInfoText>
                    <S.QueryInfoText>
                      모듈 실행 시간:{' '}
                      {event.latencySeconds === null ? '미기록' : `${(event.latencySeconds * 1000).toFixed(2)} ms`}
                      {event.revisitCount > 0 ? ` · 재방문 ${event.revisitCount}회` : ''}
                    </S.QueryInfoText>
                    <TechnicalDetails
                      entries={[
                        ['질문 ID', event.queryId],
                        ['실행 단계 ID', event.executionId],
                        ['부모 실행 ID', event.parentExecutionIds],
                        ['모듈 ID', event.moduleId],
                        ['다음 모듈 ID', event.nextModules],
                        ['실패 유형', event.failureType],
                      ]}
                    />
                  </S.QueryItem>
                ),
              )
            ) : (
              <S.NoDataText>이 이력에는 실행 단계 추적 정보가 없습니다.</S.NoDataText>
            )}
          </S.ScrollableContent>
        </div>
      </S.Disclosure>

      <S.Disclosure>
        <summary>실행별 변화 살펴보기 · 평가 완료 비율과 지표별 추세</summary>
        <div>
          <S.Section>
            <div>
              <S.BoxTitleH3>모듈별 평가 완료 비율</S.BoxTitleH3>
              <S.QueryInfoText>
                기록된 평가 중 계산이 완료된 비율(%)입니다. 지표 점수나 답변 품질을 뜻하지 않습니다. 점을 선택하면 해당
                실행으로 이동합니다.
              </S.QueryInfoText>
            </div>
            <S.ChartCanvas $height={290}>
              <ResponsiveContainer
                width="100%"
                height="100%"
                minWidth={0}
                initialDimension={{ width: 480, height: 260 }}
              >
                <LineChart data={modulePerformanceData} margin={{ top: 14, right: 20, left: 0, bottom: 8 }}>
                  <CartesianGrid vertical={false} stroke="#e8edf5" />
                  <XAxis {...axis} dataKey="date" />
                  <YAxis {...axis} width={48} domain={[0, 100]} unit="%" />
                  <Tooltip contentStyle={tooltipStyle} />
                  <Legend />
                  {allModuleNames.map((moduleName, index) => (
                    <Line
                      isAnimationActive={false}
                      key={moduleName}
                      type="linear"
                      dataKey={moduleName}
                      name={moduleText(moduleName)}
                      stroke={color(index)}
                      strokeWidth={2.5}
                      dot={{ r: 4, onClick: handleDotClick, style: { cursor: 'pointer' } }}
                      activeDot={{ r: 6, onClick: handleDotClick }}
                      connectNulls={false}
                    />
                  ))}
                </LineChart>
              </ResponsiveContainer>
            </S.ChartCanvas>
            <S.DistributionGrid>
              {Object.entries(metricPerformanceBreakdownData).map(([metricName, data]) => (
                <S.ChartBox key={metricName}>
                  <S.BoxTitleH3>{metricText(metricName)}</S.BoxTitleH3>
                  <S.QueryInfoText>단위·평가 조건을 분리한 점수 변화</S.QueryInfoText>
                  <S.ChartCanvas $height={250}>
                    <ResponsiveContainer
                      width="100%"
                      height="100%"
                      minWidth={0}
                      initialDimension={{ width: 480, height: 260 }}
                    >
                      <LineChart data={data} margin={{ top: 14, right: 12, left: 0, bottom: 8 }}>
                        <CartesianGrid vertical={false} stroke="#e8edf5" />
                        <XAxis {...axis} dataKey="date" />
                        <YAxis
                          {...axis}
                          width={55}
                          domain={metricChartDomains[metricName] || ['auto', 'auto']}
                          allowDataOverflow={false}
                        />
                        <Tooltip contentStyle={tooltipStyle} />
                        <Legend />
                        {chartLines()}
                      </LineChart>
                    </ResponsiveContainer>
                  </S.ChartCanvas>
                </S.ChartBox>
              ))}
            </S.DistributionGrid>
          </S.Section>
        </div>
      </S.Disclosure>

      {zoomedMetric && (
        <MetricDialog
          title={metricText(zoomedMetric)}
          description={`${selectedRunLabel} · ${moduleText(selectedModule)} · ${aggregationLabel}`}
          onClose={handleZoomOut}
        >
          <S.ZoomedViewContainer>
            <S.ZoomedChartWrapper>
              <S.BoxTitleH3>점수 구간으로 표본 살펴보기</S.BoxTitleH3>
              <S.QueryInfoText>
                막대 또는 아래 선택 상자로 구간을 고르세요. 구간 경계와 표본 집계는 분포 차트와 같습니다.
              </S.QueryInfoText>
              <S.ChartCanvas $height={260}>
                <ResponsiveContainer
                  width="100%"
                  height="100%"
                  minWidth={0}
                  initialDimension={{ width: 480, height: 260 }}
                >
                  <BarChart data={zoomedFrequencyData} margin={{ top: 14, right: 12, left: 0, bottom: 8 }}>
                    <CartesianGrid vertical={false} stroke="#e8edf5" />
                    <XAxis {...axis} dataKey="range" interval="preserveStartEnd" />
                    <YAxis {...axis} width={38} allowDecimals={false} />
                    <Tooltip contentStyle={tooltipStyle} cursor={{ fill: '#f0f3f9' }} />
                    <Bar
                      isAnimationActive={false}
                      dataKey="count"
                      name={aggregation === 'step' ? '실행 표본 수' : '질문 표본 수'}
                      radius={[4, 4, 0, 0]}
                      maxBarSize={44}
                    >
                      {zoomedFrequencyData.map((entry, index) => (
                        <Cell
                          key={index}
                          fill={selectedBinIndex === index ? '#087f70' : '#4f46e5'}
                          cursor="pointer"
                          onClick={() => handleFrequencyBarClick(entry)}
                        />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </S.ChartCanvas>
              <label>
                <S.QueryInfoText as="span">점수 구간 선택</S.QueryInfoText>
                <S.BinSelect
                  aria-label="점수 구간 선택"
                  value={selectedBinIndex < 0 ? '' : String(selectedBinIndex)}
                  onChange={(event) =>
                    handleFrequencyBarClick(
                      event.target.value === '' ? null : zoomedFrequencyData[Number(event.target.value)],
                    )
                  }
                >
                  <option value="">전체 평가 완료 표본</option>
                  {zoomedFrequencyData.map((bin, index) => (
                    <option key={index} value={index}>
                      {bin.range} · {bin.count}건
                    </option>
                  ))}
                </S.BinSelect>
              </label>
              <S.QueryInfoText>
                미평가 표본은 제외됩니다. 상세 점수의 단위는 각 지표에 선언된 값을 유지합니다.
              </S.QueryInfoText>
            </S.ZoomedChartWrapper>
            <S.ZoomedQueryWrapper>
              <S.BoxHeader>
                <S.BoxTitleH3>질문·답변과 평가 근거</S.BoxTitleH3>
                <S.Badge>{detailedQueryData?.length || 0}건</S.Badge>
              </S.BoxHeader>
              <S.QueryInfoText>
                선택 구간: {selectedScoreRange ? `${selectedScoreRange[0]}–${selectedScoreRange[1]}` : '전체'}
              </S.QueryInfoText>
              {aggregation === 'query' && (
                <S.QueryInfoText>
                  표시 점수는 질문별 실행 평균입니다. 아래 답변·근거·범위는 집계에서 마지막으로 사용된 평가 기록입니다.
                  반복별 근거는 ‘모든 실행 단계’에서 확인하세요.
                </S.QueryInfoText>
              )}
              <S.ScrollableContent style={{ maxHeight: '58dvh' }}>
                {detailedQueryData?.length ? (
                  detailedQueryData.map((q, i) => (
                    <S.QueryItem key={i}>
                      <S.QueryText>
                        {queryText(q.queryId, q.query)}
                        {q.executionIndex ? ` · 모듈 ${q.executionIndex}회차` : ''}
                      </S.QueryText>
                      <S.ScoreWrapper>
                        <S.MetricName>{metricText(zoomedMetric)}</S.MetricName>
                        <S.ScoreText>
                          {q.score.toPrecision(4)} {q.unit}
                        </S.ScoreText>
                      </S.ScoreWrapper>
                      <details>
                        <summary style={{ color: 'var(--accent)', fontSize: 13, cursor: 'pointer' }}>
                          생성된 답변 확인
                        </summary>
                        <S.QueryInfoText style={{ whiteSpace: 'pre-wrap', marginTop: 8 }}>
                          {q.answer || '답변 없음'}
                        </S.QueryInfoText>
                      </details>
                      <TechnicalDetails entries={[['질문 ID', q.queryId]]} />
                      {q.metric && <MetricDetails metric={q.metric} />}
                    </S.QueryItem>
                  ))
                ) : (
                  <S.NoDataText>
                    이 구간에 평가 완료 표본이 없습니다.
                    <br />
                    다른 점수 구간을 선택하세요.
                  </S.NoDataText>
                )}
              </S.ScrollableContent>
            </S.ZoomedQueryWrapper>
          </S.ZoomedViewContainer>
        </MetricDialog>
      )}
    </S.DashboardContainer>
  );
};
