export type ExecutionKind = 'query' | 'batch';
export type RequestStatus = 'queued' | 'running' | 'completed' | 'failed' | 'unknown';
export const EXECUTION_TOPICS = new Set(['test-query', 'run-rag-file-query', 'run-rag-llm-query']);
export const EXECUTION_EVENTS = new Set(['rag-on', 'module-statu', 'ended-query', 'rag-result-data', 'request-status']);
export type ExecutionRequest = {
  id: string;
  order: number;
  kind: ExecutionKind;
  label: string;
  topic: string;
  input: string;
  status: RequestStatus;
  disconnected: boolean;
  totalQueries: number;
  completedQueryIds: string[];
  queryIds: string[];
  runIds: string[];
  events: any[];
  result?: any;
  error?: string;
  warning?: string;
  persisted?: boolean;
  navigationHandled?: boolean;
  acknowledged?: boolean;
  serverStatusConfirmed?: boolean;
  sent?: boolean;
};
const object = (value: any) => value && typeof value === 'object' && !Array.isArray(value);
const ids = (value: any): string[] =>
  Array.isArray(value) ? value.filter((id): id is string => typeof id === 'string' && id.length > 0) : [];
const unique = (values: string[]) => Array.from(new Set(values));
export function resultStatus(states: Record<string, any>, persisted?: boolean): RequestStatus {
  const summaries = Object.values(states).map((state) => state?.execution_summary);
  if (persisted === false || summaries.some((summary) => summary?.success === false || summary?.terminated === true))
    return 'failed';
  return summaries.length > 0 && summaries.every((summary) => summary?.success === true && summary?.terminated !== true)
    ? 'completed'
    : 'unknown';
}
export const requestFinished = (request?: ExecutionRequest | null) =>
  !!request && ['completed', 'failed'].includes(request.status);
export const requestNeedsRecovery = (request?: ExecutionRequest | null) =>
  !!request && (request.disconnected || request.status === 'unknown' || (requestFinished(request) && !request.result));
export function requestStatusText(request: ExecutionRequest): string {
  if (request.sent === false) return request.error || '요청을 전송하지 못했습니다. 서버 연결을 확인하세요.';
  if (request.status === 'failed' && request.error && !request.result)
    return `요청을 처리하지 못했습니다. ${request.error}`;
  if (!request.acknowledged && !request.disconnected)
    return '요청을 전송했습니다. 서버의 접수 응답을 기다리고 있습니다.';
  if (request.status === 'failed' && (request.warning || (request.result && request.persisted === false)))
    return '결과를 저장하지 못했습니다. 현재 결과와 저장 상태를 확인하세요.';
  if (request.disconnected) return '연결이 끊겨 처리 상태를 확인하고 있습니다.';
  return {
    queued: '서버의 실행 순서를 기다리고 있습니다.',
    running: '질문 실행과 평가를 진행하고 있습니다.',
    completed: request.result
      ? '실행 처리가 끝났습니다. 질문별 성공·실패와 평가 결과를 확인하세요.'
      : '실행 처리는 끝났으며 저장된 결과를 확인하고 있습니다.',
    failed: request.result
      ? '실패한 질문의 사유와 요청 처리 오류를 결과에서 확인하세요.'
      : '실행이 실패했습니다. 저장 기록이 있는지 확인하세요.',
    unknown: '서버에서 이 요청의 상태를 확인하지 못했습니다. 완료나 실패로 단정하지 않습니다.',
  }[request.status];
}

/** Per-tab ownership and state survive page unmount; no question-text heuristic is used. */
export class ExecutionRequests {
  private records = new Map<string, ExecutionRequest>();
  private currentIds: Partial<Record<ExecutionKind, string>> = {};
  private numbers: Record<ExecutionKind, number> = { query: 0, batch: 0 };
  private sequence = 0;
  constructor(private notify: (request: ExecutionRequest) => void = () => {}) {}
  current(kind: ExecutionKind) {
    return this.get(this.currentIds[kind]);
  }
  latestCurrent() {
    return [this.current('query'), this.current('batch')]
      .filter((request): request is ExecutionRequest => !!request)
      .sort((a, b) => b.order - a.order)[0];
  }
  get(id?: string | null) {
    return id ? this.records.get(id) : undefined;
  }
  owns(id: unknown): id is string {
    return typeof id === 'string' && this.records.has(id);
  }
  all() {
    return Array.from(this.records.values());
  }
  clearCurrent(kind: ExecutionKind) {
    delete this.currentIds[kind];
  }
  register(id: string, topic: string, input: string) {
    const existing = this.get(id);
    if (existing) return existing;
    const kind: ExecutionKind = topic === 'test-query' ? 'query' : 'batch';
    const record: ExecutionRequest = {
      id,
      order: ++this.sequence,
      kind,
      topic,
      input,
      label: `${kind === 'query' ? '질문 요청' : '실행 요청'} ${++this.numbers[kind]}`,
      status: 'queued',
      disconnected: false,
      totalQueries: 0,
      completedQueryIds: [],
      queryIds: [],
      runIds: [],
      events: [],
    };
    this.records.set(id, record);
    this.currentIds[kind] = id;
    this.notify(record);
    return record;
  }
  private update(id: string, patch: Partial<ExecutionRequest>) {
    const previous = this.get(id);
    if (!previous) return;
    const record = { ...previous, ...patch };
    this.records.set(id, record);
    this.notify(record);
    return record;
  }
  connectionLost() {
    this.all()
      .filter(
        (request) =>
          request.sent !== false && (!requestFinished(request) || !request.result || !request.serverStatusConfirmed),
      )
      .forEach((request) => this.update(request.id, { disconnected: true }));
  }
  recoverable() {
    return this.all().filter(
      (request) =>
        request.sent !== false &&
        (!requestFinished(request) || !request.result || request.disconnected || !request.serverStatusConfirmed),
    );
  }
  acknowledge(id: string) {
    this.update(id, { navigationHandled: true });
  }
  failToSend(id: string) {
    const request = this.update(id, {
      sent: false,
      status: 'failed',
      error: '서버에 요청을 보내지 못했습니다. 연결을 확인한 뒤 새로 실행하세요.',
    });
    if (request && this.currentIds[request.kind] === id) this.clearCurrent(request.kind);
  }
  /** False means this event does not belong to this tab, or would regress a finished request. */
  accept(message: any): boolean {
    if (!this.owns(message?.request_id)) return false;
    const request = this.get(message.request_id)!;
    const topic = message.topic;
    if (!request.acknowledged) this.update(request.id, { acknowledged: true });
    if (topic === 'request-status') {
      const status = message.status as RequestStatus;
      if (!['queued', 'running', 'completed', 'failed', 'unknown'].includes(status)) return false;
      if (requestFinished(request) && ['queued', 'running', 'unknown'].includes(status)) return false;
      this.update(request.id, {
        status,
        serverStatusConfirmed: status === 'completed' || status === 'failed',
        disconnected: false,
        queryIds: unique([...request.queryIds, ...ids(message.query_ids)]),
        runIds: unique([...request.runIds, ...ids(message.run_ids)]),
        ...(typeof message.persisted === 'boolean' ? { persisted: message.persisted } : {}),
      });
      return true;
    }
    if (topic === 'rag-result-data') {
      if (!object(message.storage?.states)) return false;
      const states = Object.fromEntries(
        Object.entries(message.storage.states).filter(
          ([, state]: any) =>
            object(state) && (!state.run_metadata?.request_id || state.run_metadata.request_id === request.id),
        ),
      );
      if (!Object.keys(states).length) return false;
      const result = { ...message, storage: { ...message.storage, states } };
      this.update(request.id, {
        result,
        status: request.status === 'failed' ? 'failed' : resultStatus(states, message.persisted),
        disconnected: false,
        queryIds: unique([...request.queryIds, ...Object.keys(states)]),
        ...(typeof message.persisted === 'boolean' ? { persisted: message.persisted } : {}),
      });
      return true;
    }
    if (topic === 'error') {
      const text =
        typeof message.message === 'string' ? message.message : '실행 오류가 발생했습니다. 저장된 결과를 확인하세요.';
      if (message.module === 'history') this.update(request.id, { warning: text, persisted: false });
      else this.update(request.id, { status: 'failed', error: text, disconnected: false });
      return true;
    }
    if (requestFinished(request)) return false;
    if (topic === 'rag-on') {
      this.update(request.id, {
        status: 'running',
        disconnected: false,
        totalQueries:
          Number.isInteger(message['query-num']) && message['query-num'] >= 0
            ? message['query-num']
            : request.totalQueries,
      });
    } else if (topic === 'module-statu' || topic === 'ended-query') {
      const queryId = topic === 'ended-query' ? message['end-query'] : message.query_id;
      this.update(request.id, {
        status: 'running',
        disconnected: false,
        events: [...request.events, message],
        queryIds: unique([...request.queryIds, ...ids([queryId])]),
        runIds: unique([...request.runIds, ...ids([message.run_id])]),
        completedQueryIds:
          topic === 'ended-query'
            ? unique([...request.completedQueryIds, ...ids([queryId])])
            : request.completedQueryIds,
      });
    } else return false;
    return true;
  }
  /** Shared history is readable, but only an exact owned request ID can restore its request result. */
  acceptHistory(history: unknown) {
    if (!object(history)) return;
    for (const [timestamp, states] of Object.entries(history as Record<string, any>)) {
      if (!object(states)) continue;
      const grouped = new Map<string, Record<string, any>>();
      for (const [queryId, state] of Object.entries(states) as [string, any][]) {
        const id = state?.run_metadata?.request_id;
        if (!this.owns(id)) continue;
        const group = grouped.get(id) || {};
        group[queryId] = state;
        grouped.set(id, group);
      }
      grouped.forEach((ownedStates, id) => {
        const previous = this.get(id)!;
        const derived = resultStatus(ownedStates, true);
        const knownTerminal = derived !== 'unknown';
        this.update(id, {
          ...(knownTerminal ? { status: derived, disconnected: false, acknowledged: true } : {}),
          result: {
            topic: 'rag-result-data',
            fromHistory: true,
            request_id: id,
            ts: timestamp,
            persisted: true,
            storage: { states: ownedStates },
          },
          persisted: true,
          queryIds: unique([...previous.queryIds, ...Object.keys(ownedStates)]),
          runIds: unique([
            ...previous.runIds,
            ...Object.values(ownedStates).flatMap((state: any) => ids([state?.run_metadata?.run_id])),
          ]),
        });
      });
    }
  }
}
