import {
  ExecutionRequests,
  EXECUTION_TOPICS,
  EXECUTION_EVENTS,
  ExecutionKind,
  ExecutionRequest,
  requestFinished,
  requestNeedsRecovery,
} from './executionRequests';

declare global {
  interface Window {
    __RAGANG_SESSION_TOKEN__?: string;
  }
}

/** Browser transport retains subscriptions, but never logs prompts, responses, or session tokens. */
export class SocketClient {
  private ws: WebSocket | null = null;
  private url: string;
  private handlers: Record<string, ((data: any) => void)[]> = {};
  private subscriptions = new Set<string>([...Array.from(EXECUTION_EVENTS), 'error', 'history']);
  private retryCount = 0;
  private maxRetries = 10;
  private messageQueue: any[] = [];
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private stopped = false;
  private requests = new ExecutionRequests((request) => this.emit('execution-request', request));
  constructor(url?: string) {
    this.url = url || process.env.REACT_APP_WS_URL || 'ws://127.0.0.1:8081';
  }
  connect() {
    this.stopped = false;
    if (this.ws && (this.ws.readyState === WebSocket.OPEN || this.ws.readyState === WebSocket.CONNECTING)) return;
    if (this.retryCount >= this.maxRetries) {
      this.emit('connection-state', {
        status: 'disconnected',
        message: '연결을 복구하지 못했습니다. 서버 실행 상태를 확인하고 다시 연결하세요.',
      });
      return;
    }
    try {
      const token = typeof window !== 'undefined' ? window.__RAGANG_SESSION_TOKEN__ : undefined;
      const url = new URL(this.url);
      if (token) url.searchParams.set('session_token', token);
      const connection = new WebSocket(url.toString());
      this.ws = connection;
      connection.onopen = () => {
        if (connection !== this.ws) return;
        const recovered = this.retryCount > 0;
        this.retryCount = 0;
        if (this.subscriptions.size) this.send({ topic: 'subscribe', topics: Array.from(this.subscriptions) });
        const queued = this.messageQueue.splice(0);
        queued.forEach((message) => this.send(message));
        this.emit('connection-state', { status: 'connected', recovered });
        this.requests
          .recoverable()
          .forEach((request) => this.send({ topic: 'get-request-status', request_id: request.id }));
        // Reload persisted history after every reconnection; consumers already subscribed above.
        if (recovered) this.send({ topic: 'start!' });
      };
      connection.onmessage = (event) => {
        if (connection !== this.ws) return;
        try {
          const message = JSON.parse(event.data);
          if (!message || typeof message.topic !== 'string') return;
          if (message.topic === 'history') this.requests.acceptHistory(message.history);
          if (EXECUTION_EVENTS.has(message.topic) || (message.topic === 'error' && message.request_id)) {
            if (!this.requests.accept(message)) return;
            this.emit(
              message.topic,
              message.topic === 'rag-result-data' ? this.requests.get(message.request_id)?.result : message,
            );
            if (
              message.topic === 'request-status' &&
              ['completed', 'failed'].includes(message.status) &&
              !this.requests.get(message.request_id)?.result
            )
              this.send({ topic: 'start!' });
          } else this.emit(message.topic, message);
        } catch {
          this.emit('connection-state', { status: 'error', message: '서버 메시지를 읽지 못했습니다.' });
        }
      };
      connection.onerror = () => {
        if (connection !== this.ws) return;
        this.requests.connectionLost();
        this.emit('connection-state', { status: 'error', message: '서버 연결을 확인하세요.' });
      };
      connection.onclose = () => {
        if (connection !== this.ws) return;
        this.ws = null;
        if (this.stopped) return;
        this.retryCount++;
        this.requests.connectionLost();
        this.emit('connection-state', {
          status: 'reconnecting',
          message: '연결 복구 중입니다. 기존 결과는 유지됩니다.',
        });
        this.reconnectTimer = setTimeout(() => this.reconnectAfterBootstrap(), 3000);
      };
    } catch {
      this.emit('connection-state', { status: 'error', message: '서버 주소를 확인하세요.' });
    }
  }
  private emit(topic: string, data: any) {
    (this.handlers[topic] || []).slice().forEach((handler) => handler(data));
  }
  private reconnectAfterBootstrap() {
    if (this.stopped) return;
    // A restarted local server issues a new token. Reload only its same-origin
    // bootstrap, never reuse a cached token or evaluate response strings.
    if (typeof window === 'undefined' || typeof document === 'undefined') {
      this.connect();
      return;
    }
    const script = document.createElement('script');
    script.src = '/ragang-session.js';
    script.async = true;
    const complete = () => {
      script.remove();
      if (!this.stopped) this.connect();
    };
    script.onload = complete;
    script.onerror = complete;
    document.head.appendChild(script);
  }
  on(topic: string, handler: (data: any) => void) {
    if (!this.handlers[topic]) this.handlers[topic] = [];
    if (!this.handlers[topic].includes(handler)) this.handlers[topic].push(handler);
  }
  off(topic: string, handler: (data: any) => void) {
    this.handlers[topic] = (this.handlers[topic] || []).filter((h) => h !== handler);
  }
  send(message: any): boolean {
    const execution = EXECUTION_TOPICS.has(message?.topic);
    // An execution is sent once on an open connection. It is never queued or replayed.
    if (execution && (!this.requests.owns(message.request_id) || this.ws?.readyState !== WebSocket.OPEN)) return false;
    if (this.ws?.readyState === WebSocket.OPEN) {
      try {
        this.ws.send(JSON.stringify(message));
        return true;
      } catch {
        return false;
      }
    }
    if (!execution && !this.messageQueue.some((queued) => JSON.stringify(queued) === JSON.stringify(message)))
      this.messageQueue.push(message);
    return false;
  }
  startRequest(topic: string, payload: Record<string, any>): ExecutionRequest | false {
    if (
      !EXECUTION_TOPICS.has(topic) ||
      this.ws?.readyState !== WebSocket.OPEN ||
      typeof crypto === 'undefined' ||
      typeof crypto.randomUUID !== 'function'
    )
      return false;
    const current = this.requests.current(topic === 'test-query' ? 'query' : 'batch');
    if (current && (!requestFinished(current) || requestNeedsRecovery(current))) return false;
    const id = crypto.randomUUID();
    const input = topic === 'test-query' ? payload.query : payload.settings?.file_name;
    const request = this.requests.register(id, topic, typeof input === 'string' ? input : '');
    if (!this.send({ ...payload, topic, request_id: id })) {
      this.requests.failToSend(id);
      return false;
    }
    return request;
  }
  latestRequest() {
    return this.requests.latestCurrent();
  }
  currentRequest(kind: ExecutionKind) {
    return this.requests.current(kind);
  }
  getRequest(id: string) {
    return this.requests.get(id);
  }
  acknowledgeRequest(id: string) {
    this.requests.acknowledge(id);
  }
  ownsRequest(id: unknown) {
    return this.requests.owns(id);
  }
  clearCurrentRequest(kind: ExecutionKind) {
    this.requests.clearCurrent(kind);
  }
  refreshRequest(id: string) {
    if (!this.requests.owns(id)) return false;
    const sent = this.send({ topic: 'get-request-status', request_id: id });
    this.send({ topic: 'start!' });
    return sent;
  }
  subscribe(topics: string[]) {
    topics.forEach((t) => this.subscriptions.add(t));
    if (this.ws?.readyState === WebSocket.OPEN) this.send({ topic: 'subscribe', topics });
  }
  unsubscribe(topics: string[]) {
    topics.forEach((t) => this.subscriptions.delete(t));
    if (this.ws?.readyState === WebSocket.OPEN) this.send({ topic: 'unsubscribe', topics });
  }
  sendTestQuery(query: string) {
    return this.startRequest('test-query', { query });
  }
  sendFileQuery(files: string[]) {
    return files[0] ? this.startRequest('run-rag-file-query', { settings: { file_name: files[0] } }) : false;
  }
  sendLLMQuery(settings: { file_name: string }) {
    return this.startRequest('run-rag-llm-query', { settings });
  }
  reconnect() {
    this.retryCount = 0;
    this.stopped = false;
    this.reconnectAfterBootstrap();
  }
  disconnect() {
    this.stopped = true;
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    const connection = this.ws;
    this.ws = null;
    if (connection) this.requests.connectionLost();
    connection?.close();
  }
}
export const socket = new SocketClient();
