import React, { type ReactNode } from 'react';
import { BarChart3, Layers3, ListChecks, Workflow } from 'lucide-react';
import * as S from './Header.styled';
import fontLicense from '../../assets/fonts/Pretendard-LICENSE.txt';

/** Navigation stays short while every workspace view has a stable route. */
export const Header: React.FC = () => (
  <S.HeaderContainer>
    <S.TitleWrapper to="/dashboard" aria-label="RAGANG 홈">
      <S.BrandMark aria-hidden="true">
        <Layers3 size={22} strokeWidth={1.8} />
      </S.BrandMark>
      <S.BrandCopy>
        <S.Title>RAGANG</S.Title>
        <S.Subtitle>RAG 평가 워크스페이스</S.Subtitle>
      </S.BrandCopy>
    </S.TitleWrapper>
    <S.NavLabel>워크스페이스</S.NavLabel>
    <S.Nav aria-label="주요 메뉴">
      <S.NavItem to="/dashboard">
        <BarChart3 size={18} aria-hidden="true" />
        평가 결과
      </S.NavItem>
      <S.NavItem to="/test">
        <Workflow size={18} aria-hidden="true" />
        실시간 검증
      </S.NavItem>
      <S.NavItem to="/run-queries">
        <ListChecks size={18} aria-hidden="true" />
        일괄 평가
      </S.NavItem>
    </S.Nav>
    <S.Footer>
      <strong>내 RAG를 이해하는 과정</strong>검색부터 답변까지,
      <br />
      근거와 실행을 함께 확인하세요.
      <a href={fontLicense} target="_blank" rel="noreferrer">
        글꼴 라이선스
      </a>
    </S.Footer>
  </S.HeaderContainer>
);

/** Pure layout can be checked independently from socket and evaluation state. */
export function AppLayout({ children }: { children: ReactNode }) {
  const focusMainContent = (event: React.MouseEvent<HTMLAnchorElement>) => {
    // HashRouter owns the URL fragment, so a native fragment jump would change routes.
    event.preventDefault();
    const main = event.currentTarget.ownerDocument.getElementById('main-content');
    main?.focus();
    main?.scrollIntoView({ block: 'start' });
  };

  return (
    <S.AppShell>
      <S.SkipLink href="#main-content" onClick={focusMainContent}>
        본문으로 바로가기
      </S.SkipLink>
      <Header />
      <S.MainContent id="main-content" tabIndex={-1}>
        {children}
      </S.MainContent>
    </S.AppShell>
  );
}
