/**
 * 아코디언 컴포넌트
 * @param title 헤더로 렌더할 ReactNode
 * @param children 펼쳐지는 내용
 */

import React, { useState, useId, ReactNode } from 'react';
import * as S from './Accordion.styled';
import { ChevronRight } from 'lucide-react';

interface AccordionProps {
  title: ReactNode; // 제목으로 JSX를 받을 수 있도록 ReactNode 타입 사용
  children: ReactNode;
}

export const Accordion: React.FC<AccordionProps> = ({ title, children }) => {
  const id = useId();
  const [isOpen, setIsOpen] = useState(false); // 아코디언 열림/닫힘 상태

  const toggleAccordion = () => {
    setIsOpen(!isOpen);
  };

  return (
    <S.AccordionWrapper>
      {/* 아코디언 헤더(제목). 클릭 시 toggleAccordion 함수 실행 */}
      <S.AccordionHeader
        type="button"
        id={`${id}-trigger`}
        onClick={toggleAccordion}
        aria-expanded={isOpen}
        aria-controls={`${id}-content`}
      >
        {title}
        <ChevronRight size={20} className="icon" />
      </S.AccordionHeader>
      {/* isOpen 상태가 true일 때만 콘텐츠 표시 */}
      {isOpen && (
        <S.AccordionContent id={`${id}-content`} role="region" aria-labelledby={`${id}-trigger`}>
          {children}
        </S.AccordionContent>
      )}
    </S.AccordionWrapper>
  );
};
