import type { MetricScore } from '../../globals/types';
import type { LiveMetric } from '../../globals/recoil/atoms';
import { metricIdentity } from '../Dashboard/analysis';
import { declaredUnitDomain, ChartDomain } from '../../utils/chartDomain';

export type LiveSeriesDomain = ChartDomain;

/** A declared bounded scale guides the axis; observed values are never clipped or converted. */
export function liveSeriesDomain(
  series: string,
  groups: { moduleName: string; metrics: MetricScore[] }[],
  history: LiveMetric[],
): LiveSeriesDomain {
  const unit = groups.reduce<string | undefined>(
    (found, group) =>
      found ?? group.metrics.find((metric) => `${group.moduleName} · ${metricIdentity(metric)}` === series)?.unit,
    undefined,
  );
  return declaredUnitDomain(
    unit,
    history.map((row) => row[series]),
  );
}
