import React from 'react';
import * as S from './KPICard.styled';
interface KPICardProps {
  title: string;
  value: string;
  description?: string;
  tone?: 'success' | 'danger' | 'accent' | 'neutral';
  change?: { value: string; isPositive: boolean };
}
export const KPICard: React.FC<KPICardProps> = ({ title, value, description, tone, change }) => (
  <S.CardContainer $tone={tone}>
    <S.CardTitle>{title}</S.CardTitle>
    <S.CardValue>{value}</S.CardValue>
    {description && <S.CardDescription>{description}</S.CardDescription>}
    {change && <S.CardChange $isPositive={change.isPositive}>{change.value}</S.CardChange>}
  </S.CardContainer>
);
