import React, { useEffect, useMemo, useState, useRef } from 'react';
import { useRecoilState } from 'recoil';
import { MarkerType } from 'reactflow';
import { testQueryState } from '../../globals/recoil/atoms';
import type { ModuleStatus } from '../../globals/recoil/atoms';
import { TestQueryView } from './TestQueryView';
import * as S from './TestQuery.styled';
import { socket } from '../../apis/socket';
import { layoutGraph, GraphPair } from './graph';
import { TechnicalDetails } from '../../components/TechnicalDetails';
import { moduleDisplayNames, questionDisplayName } from '../../utils/display';
import {
  appendLiveResult,
  normalizedStatus,
  statusKey,
  appendExecutionStatus,
  queryExecutionDetail,
  LiveQueryDetail,
} from './liveData';
import { useExecutionRequest } from '../../apis/useExecutionRequest';
import { requestFinished, requestNeedsRecovery, requestStatusText } from '../../apis/executionRequests';

export const TestQueryPage: React.FC = () => {
  const [moduleIds, setModuleIds] = useState<string[]>([]),
    [modulePairs, setModulePairs] = useState<GraphPair[]>([]);
  const [state, setState] = useRecoilState(testQueryState);
  const { request, start, clear } = useExecutionRequest('query');
  const [activeQuery, setActiveQuery] = useState('');
  const [queryLabels, setQueryLabels] = useState<Record<string, string>>({});
  const [savedStates, setSavedStates] = useState<Record<string, any>>({});
  const [details, setDetails] = useState<Record<string, LiveQueryDetail>>({});
  const [error, setError] = useState('');
  const autoSelect = useRef(true);
  useEffect(() => {
    const topology = (data: any) => {
      if (Array.isArray(data['rag-container'])) setModulePairs(data['rag-container']);
      if (Array.isArray(data.module_ids)) setModuleIds(data.module_ids.filter((id: any) => typeof id === 'string'));
    };
    const connection = (data: any) => {
      if (data.status === 'connected') {
        setError('');
        socket.send({ topic: 'get-module-pairs' });
      } else if (['disconnected', 'error', 'reconnecting'].includes(data.status))
        setError(typeof data.message === 'string' ? data.message : '서버 연결을 확인하세요.');
    };
    const history = (data: any) => {
      const states: Record<string, any> = {};
      Object.values(data.history || {}).forEach((run) => {
        if (run && typeof run === 'object' && !Array.isArray(run)) Object.assign(states, run);
      });
      setSavedStates((previous) => ({ ...previous, ...states }));
      setQueryLabels((previous) => ({
        ...previous,
        ...Object.fromEntries(
          Object.entries(states).map(([id, value]) => [id, typeof value?.query === 'string' ? value.query : '']),
        ),
      }));
      setDetails((previous) => ({
        ...previous,
        ...Object.fromEntries(Object.entries(states).map(([id, value]) => [id, queryExecutionDetail(value)])),
      }));
      // Shared history only populates choices; it never appends another user's answer or takes selection.
    };
    const listeners = { 'rag-container': topology, 'connection-state': connection, history };
    Object.entries(listeners).forEach(([topic, callback]) => socket.on(topic, callback));
    socket.subscribe(['rag-container', 'history']);
    socket.send({ topic: 'get-module-pairs' });
    socket.send({ topic: 'start!' });
    return () => Object.entries(listeners).forEach(([topic, callback]) => socket.off(topic, callback));
  }, []);
  useEffect(() => {
    if (!request) return;
    const nextDetails: Record<string, LiveQueryDetail> = {},
      statuses: Record<string, any> = {},
      labels: Record<string, string> = {};
    request.events.forEach((message) => {
      const id = message.topic === 'ended-query' ? message['end-query'] : message.query_id;
      if (typeof id !== 'string') return;
      labels[id] = request.input;
      if (message.topic === 'module-statu') {
        nextDetails[id] = appendExecutionStatus(nextDetails[id], message);
        statuses[statusKey(message.module, id)] = normalizedStatus(message);
      } else if (message.topic === 'ended-query')
        nextDetails[id] = {
          ...(nextDetails[id] || { query: request.input, executions: [] }),
          outcome: message.status === 'failed' ? 'failed' : message.status === 'completed' ? 'completed' : undefined,
        };
    });
    const resultStates = request.result?.storage?.states;
    if (resultStates && typeof resultStates === 'object' && !Array.isArray(resultStates)) {
      Object.entries(resultStates).forEach(([id, value]) => {
        nextDetails[id] = queryExecutionDetail(value);
        labels[id] = nextDetails[id].query;
        nextDetails[id].executions.forEach((event) => (statuses[statusKey(event.moduleId, id)] = event.status));
      });
      setSavedStates((previous) => ({ ...previous, ...resultStates }));
      setState((previous) =>
        appendLiveResult(previous, resultStates, request.result?.fromHistory === true ? 'history' : 'live'),
      );
    }
    setQueryLabels((previous) => ({ ...previous, ...labels }));
    setDetails((previous) => ({ ...previous, ...nextDetails }));
    setState((previous) => ({ ...previous, moduleStatuses: { ...previous.moduleStatuses, ...statuses } }));
    const first = Object.keys(nextDetails)[0];
    if (autoSelect.current && first) {
      setActiveQuery(first);
      autoSelect.current = false;
    }
  }, [request, setState]);
  const graph = useMemo(() => layoutGraph(modulePairs, moduleIds), [modulePairs, moduleIds]);
  const moduleLabels = moduleDisplayNames([
    ...graph.nodes.map((node) => node.id),
    ...state.metrics.map((group) => group.moduleName),
  ]);
  const selectedQuery = details[activeQuery];
  const counts: Record<string, number> = {};
  selectedQuery?.executions.forEach((execution) => {
    counts[execution.moduleId] = (counts[execution.moduleId] || 0) + 1;
  });
  const nodes = graph.nodes.map((node) => ({
    ...node,
    type: 'moduleNode',
    data: {
      label: moduleLabels[node.id],
      status:
        state.moduleStatuses[statusKey(node.id, activeQuery)] ||
        (!activeQuery ? state.moduleStatuses[node.id] : '') ||
        'pending',
      repetitions: counts[node.id],
    },
    draggable: false,
  }));
  const edges = graph.edges.map((edge) => ({
    ...edge,
    sourceHandle: edge.isFeedback ? 'feedback-out' : 'out',
    targetHandle: edge.isFeedback ? 'feedback-in' : 'in',
    type: edge.isFeedback ? 'feedback' : 'smoothstep',
    data: { laneX: edge.laneX },
    markerEnd: { type: MarkerType.ArrowClosed, color: edge.isFeedback ? '#b16a1b' : '#91a0b7' },
    style: {
      stroke: edge.isFeedback ? '#b16a1b' : '#91a0b7',
      strokeWidth: 1.7,
      strokeDasharray: edge.isFeedback ? '6 4' : undefined,
    },
  }));
  const reset = () => {
    const current = socket.currentRequest('query');
    if (current && !requestFinished(current)) {
      setError('현재 요청의 처리 상태를 먼저 확인하세요. 기록 초기화는 실행 취소가 아닙니다.');
      return;
    }
    clear();
    setState({
      messages: [],
      metrics: [],
      moduleStatuses: {},
      liveMetricsHistory: [],
      activeConnections: [],
      processedQueryIds: [],
    });
    setQueryLabels({});
    setDetails({});
    setSavedStates({});
    setActiveQuery('');
    setError('');
    autoSelect.current = false;
  };
  const send = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const input = event.currentTarget.queryInput as HTMLInputElement,
      query = input.value.trim();
    if (!query) return;
    const sent = start('test-query', { query });
    if (!sent) {
      setError(
        socket.currentRequest('query') && !requestFinished(socket.currentRequest('query'))
          ? '현재 질문 요청의 처리 상태를 먼저 확인하세요. 실행 요청을 추가로 보내지 않았습니다.'
          : '서버에 연결되지 않아 질문을 보내지 않았습니다. 연결을 확인한 뒤 다시 실행하세요.',
      );
      return;
    }
    autoSelect.current = true;
    setActiveQuery('');
    setError('');
    setState((previous) => ({ ...previous, messages: [...previous.messages, { sender: 'user', text: query }] }));
    input.value = '';
  };
  const selectQuery = (id: string) => {
    autoSelect.current = false;
    setActiveQuery(id);
    if (savedStates[id]) {
      const recorded = queryExecutionDetail(savedStates[id]);
      const statuses = Object.fromEntries(
        recorded.executions.map((event) => [statusKey(event.moduleId, id), event.status as ModuleStatus]),
      );
      setState((previous) => ({
        ...appendLiveResult(previous, { [id]: savedStates[id] }, 'history'),
        moduleStatuses: { ...previous.moduleStatuses, ...statuses },
      }));
    }
  };
  const repeatCount = Object.values(counts).reduce((sum, count) => sum + Math.max(0, count - 1), 0);
  return (
    <>
      <S.PageHeader>
        <div>
          <S.Eyebrow>LIVE VALIDATION</S.Eyebrow>
          <h1>질문 하나로 흐름을 검증하세요</h1>
          <p>검색 분기, 병합, 순환이 포함된 RAG를 실행하고 어느 단계에서 무엇이 평가되었는지 확인하세요.</p>
        </div>
      </S.PageHeader>
      {error && <S.Alert role="alert">{error}</S.Alert>}
      {request && (
        <S.Description
          role="status"
          style={{ padding: '14px 18px', background: 'var(--accent-soft)', borderRadius: 10 }}
        >
          <strong>{request.label}</strong> · {requestStatusText(request)}
          <br />
          요청 번호는 이 탭의 전송 순서이며 질문 번호·실행 번호와는 다릅니다.
          <S.ResetButton style={{ marginTop: 8 }} onClick={() => socket.refreshRequest(request.id)}>
            이 요청 상태 확인
          </S.ResetButton>
          {requestNeedsRecovery(request) && (
            <>
              <p>새 요청을 준비해도 기존 요청은 취소되지 않으며 서버에서 계속 처리될 수 있습니다.</p>
              <S.ResetButton
                onClick={() => {
                  clear();
                  autoSelect.current = false;
                  setActiveQuery('');
                  setError('기존 요청은 취소하지 않았습니다. 서버에서 계속 처리될 수 있습니다.');
                }}
              >
                기존 요청 유지하고 새 질문 준비
              </S.ResetButton>
            </>
          )}
        </S.Description>
      )}
      {(request?.error || request?.warning) && <S.Alert role="alert">{request.error || request.warning}</S.Alert>}
      <S.SelectionBar>
        <label>
          상태를 볼 질문
          <select
            aria-label="상태를 볼 질문"
            value={activeQuery}
            onChange={(event) => selectQuery(event.target.value)}
            disabled={!Object.keys(queryLabels).length}
          >
            {!activeQuery && (
              <option value="">
                {request && !requestFinished(request)
                  ? '현재 질문 요청의 응답을 기다리는 중'
                  : '질문을 직접 선택하세요'}
              </option>
            )}
            {Object.entries(queryLabels).map(([id, label], index) => (
              <option value={id} key={id}>
                {questionDisplayName(label, index + 1)}
              </option>
            ))}
          </select>
        </label>
        <S.Stats>
          <div>
            <strong>{graph.nodes.length}</strong>선언된 모듈
          </div>
          <div>
            <strong>{selectedQuery ? selectedQuery.executions.length : '—'}</strong>관측된 실행 단계
          </div>
          <div>
            <strong>{selectedQuery ? repeatCount : '—'}</strong>추가 반복 실행
          </div>
        </S.Stats>
      </S.SelectionBar>
      <TestQueryView
        moduleLabels={moduleLabels}
        nodes={nodes}
        edges={edges}
        graphBounds={graph.bounds}
        onNodesChange={() => {}}
        onEdgesChange={() => {}}
        messages={state.messages}
        metrics={state.metrics}
        liveMetricsHistory={state.liveMetricsHistory}
        selectedQuery={selectedQuery}
        activeQuery={activeQuery}
        handleSendMessage={send}
        handleReset={reset}
      />
      <div style={{ marginTop: 16 }}>
        <TechnicalDetails
          entries={[
            ['선택 질문 ID', activeQuery],
            ['현재 요청 ID', request?.id],
            ['요청 상태 원본', request?.status],
            ['모듈 ID와 표시 이름', moduleLabels],
          ]}
        />
      </div>
    </>
  );
};
