import { useEffect, useState, useRef } from 'react';
import { socket } from './socket';
import type { ExecutionKind, ExecutionRequest } from './executionRequests';

/** The shared transport owns records; the page follows only its current request. */
export function useExecutionRequest(kind: ExecutionKind) {
  const [request, setRequest] = useState<ExecutionRequest | undefined>(() => socket.currentRequest(kind));
  const id = useRef(request?.id);
  useEffect(() => {
    const receive = (next: ExecutionRequest) => {
      if (next.kind === kind && next.id === id.current) setRequest(next);
    };
    socket.on('execution-request', receive);
    const current = socket.currentRequest(kind);
    id.current = current?.id;
    setRequest(current);
    if (current) socket.refreshRequest(current.id);
    return () => socket.off('execution-request', receive);
  }, [kind]);
  const start = (topic: string, payload: Record<string, any>) => {
    const next = socket.startRequest(topic, payload);
    if (next) {
      id.current = next.id;
      setRequest(next);
    }
    return next;
  };
  const clear = () => {
    socket.clearCurrentRequest(kind);
    id.current = undefined;
    setRequest(undefined);
  };
  return { request, start, clear };
}
