export type GraphPair = [string, string];
export const GRAPH_NODE_WIDTH = 264;
export const GRAPH_NODE_HEIGHT = 80;
export const GRAPH_FIT_VIEW_OPTIONS = { padding: 0.05, minZoom: 0.04, maxZoom: 1 };
const COLUMN_SPACING = 324;
const ROW_SPACING = 112;

/** A feedback curve is routed outside the forward layers, without inventing graph edges. */
export function feedbackPath(sourceX: number, sourceY: number, targetX: number, targetY: number, laneX: number) {
  const self = Math.abs(sourceY - targetY) < 1 && Math.abs(sourceX - targetX) < 1;
  if (self) {
    return {
      path: `M ${sourceX},${sourceY - 15} C ${laneX},${sourceY - 86} ${laneX},${sourceY + 86} ${targetX},${targetY + 15}`,
      labelX: (sourceX + 3 * laneX) / 4,
      labelY: sourceY,
    };
  }
  return {
    path: `M ${sourceX},${sourceY} C ${laneX},${sourceY} ${laneX},${targetY} ${targetX},${targetY}`,
    labelX: (sourceX + 6 * laneX + targetX) / 8,
    labelY: (sourceY + targetY) / 2,
  };
}

/**
 * SCC membership means an edge participates in a real cycle. Only DFS back edges
 * are routed as feedback; the remaining DAG retains the actual forward layers.
 * This is a deterministic drawing convention, never a claim about retry semantics
 * or the order in which the backend selected/executed these declared edges.
 */
export function layoutGraph(input: GraphPair[], additionalIds: string[] = []) {
  const pairs = (Array.isArray(input) ? input : []).filter(
    (p) => Array.isArray(p) && p.length === 2 && p.every((x) => typeof x === 'string' && x.length),
  );
  const ids = Array.from(
    new Set([...pairs.flat(), ...additionalIds.filter((id) => typeof id === 'string' && id.length)]),
  ).sort();
  const adjacency = new Map(
    ids.map((id) => [id, Array.from(new Set(pairs.filter((p) => p[0] === id).map((p) => p[1]))).sort()]),
  );
  let index = 0;
  const indexes = new Map<string, number>(),
    low = new Map<string, number>(),
    stack: string[] = [],
    onStack = new Set<string>(),
    components: string[][] = [];
  function visit(id: string) {
    indexes.set(id, index);
    low.set(id, index++);
    stack.push(id);
    onStack.add(id);
    for (const next of adjacency.get(id) || []) {
      if (!indexes.has(next)) {
        visit(next);
        low.set(id, Math.min(low.get(id)!, low.get(next)!));
      } else if (onStack.has(next)) low.set(id, Math.min(low.get(id)!, indexes.get(next)!));
    }
    if (low.get(id) === indexes.get(id)) {
      const component: string[] = [];
      let node: string;
      do {
        node = stack.pop()!;
        onStack.delete(node);
        component.push(node);
      } while (node !== id);
      components.push(component.sort());
    }
  }
  ids.forEach((id) => {
    if (!indexes.has(id)) visit(id);
  });
  const componentOf = new Map<string, number>();
  components.forEach((c, i) => c.forEach((id) => componentOf.set(id, i)));
  const indegree = new Map(ids.map((id) => [id, 0]));
  pairs.forEach(([, target]) => indegree.set(target, indegree.get(target)! + 1));
  const entries = pairs
    .filter(([source, target]) => componentOf.get(source) !== componentOf.get(target))
    .map(([, target]) => target);
  const roots = Array.from(new Set([...ids.filter((id) => indegree.get(id) === 0), ...entries.sort(), ...ids]));
  const color = new Map<string, number>(),
    feedback = new Map<string, Set<string>>();
  function traverse(id: string) {
    color.set(id, 1);
    for (const target of adjacency.get(id) || []) {
      if (color.get(target) === 1) {
        if (!feedback.has(id)) feedback.set(id, new Set());
        feedback.get(id)!.add(target);
      } else if (!color.has(target)) traverse(target);
    }
    color.set(id, 2);
  }
  roots.forEach((id) => {
    if (!color.has(id)) traverse(id);
  });
  const isFeedback = (source: string, target: string) => feedback.get(source)?.has(target) || false;
  const forward = pairs.filter(([source, target]) => !isFeedback(source, target));
  const incoming = new Map(
    ids.map((id) => [id, forward.filter(([, target]) => target === id).map(([source]) => source)]),
  );
  const degrees = new Map(ids.map((id) => [id, incoming.get(id)!.length]));
  const levels = new Map(ids.map((id) => [id, 0]));
  const queue = ids.filter((id) => degrees.get(id) === 0);
  while (queue.length) {
    const source = queue.shift()!;
    for (const [, target] of forward.filter(([from]) => from === source)) {
      levels.set(target, Math.max(levels.get(target)!, levels.get(source)! + 1));
      degrees.set(target, degrees.get(target)! - 1);
      if (degrees.get(target) === 0) queue.push(target);
    }
    queue.sort();
  }
  const rows = new Map<number, string[]>();
  ids.forEach((id) => rows.set(levels.get(id)!, [...(rows.get(levels.get(id)!) || []), id]));
  const feedbackPairs = pairs.filter(([source, target]) => isFeedback(source, target));
  const laneKeys = Array.from(
    new Set(feedbackPairs.map(([source, target]) => JSON.stringify([source, target]))),
  ).sort();
  const gutter = laneKeys.length ? 100 + laneKeys.length * 24 : 24;
  const width = Math.max(1, ...Array.from(rows.values()).map((row) => row.length)) * COLUMN_SPACING;
  const positions = new Map<string, { x: number; y: number }>();
  Array.from(rows.entries())
    .sort(([a], [b]) => a - b)
    .forEach(([level, row]) => {
      const center = (id: string) => {
        const parents = incoming
          .get(id)!
          .map((parent) => positions.get(parent)?.x)
          .filter((x): x is number => x !== undefined);
        return parents.length ? parents.reduce((a, b) => a + b, 0) / parents.length : width / 2;
      };
      row.sort((a, b) => center(a) - center(b) || (a < b ? -1 : a > b ? 1 : 0));
      const offset = (width - row.length * COLUMN_SPACING) / 2;
      row.forEach((id, column) =>
        positions.set(id, { x: gutter + offset + column * COLUMN_SPACING, y: 28 + level * ROW_SPACING }),
      );
    });
  return {
    nodes: ids.map((id) => ({ id, position: positions.get(id)! })),
    edges: pairs.map(([source, target], index) => ({
      id: `edge-${index}`,
      source,
      target,
      isCycle:
        componentOf.get(source) === componentOf.get(target) &&
        (source === target || components[componentOf.get(source)!].length > 1),
      isFeedback: isFeedback(source, target),
      laneX: 28 + Math.max(0, laneKeys.indexOf(JSON.stringify([source, target]))) * 24,
    })),
    bounds: {
      x: 0,
      y: 0,
      width: ids.length ? Math.max(...Array.from(positions.values()).map((p) => p.x + GRAPH_NODE_WIDTH)) + 28 : 320,
      height: ids.length ? Math.max(...Array.from(positions.values()).map((p) => p.y + GRAPH_NODE_HEIGHT)) + 28 : 240,
    },
  };
}
