import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { socket } from '../../apis/socket';
import { SettingsView, FileListStatus } from './SettingsView';
import { useExecutionRequest } from '../../apis/useExecutionRequest';
import { requestFinished, requestNeedsRecovery, requestStatusText } from '../../apis/executionRequests';
import { TechnicalDetails } from '../../components/TechnicalDetails';

type InputMode = 'llm-generated' | 'custom';
const fileTopic = (mode: InputMode) => (mode === 'custom' ? 'custom-query-files' : 'generated-query-files');
export const normalizeQueryFiles = (files: unknown): string[] =>
  Array.isArray(files)
    ? Array.from(
        new Set(files.filter((file): file is string => typeof file === 'string' && file.trim().length > 0)),
      ).sort()
    : [];
export const evaluationProgress = (completed: number, total: number) =>
  Number.isFinite(completed) && Number.isFinite(total) && total > 0
    ? Math.min(100, Math.max(0, Math.floor((completed / total) * 100)))
    : 0;

export const SettingsPage: React.FC = () => {
  const navigate = useNavigate();
  const { request, start, clear } = useExecutionRequest('batch');
  const [step, setStep] = useState(1),
    [error, setError] = useState('');
  const [inputMode, setInputMode] = useState<InputMode>('custom');
  const [files, setFiles] = useState<Record<InputMode, string[]>>({ custom: [], 'llm-generated': [] });
  const [fileStatuses, setFileStatuses] = useState<Record<InputMode, FileListStatus>>({
    custom: 'loading',
    'llm-generated': 'loading',
  });
  const [selectedFileName, setSelectedFileName] = useState('');
  const fileTimers = useRef<Partial<Record<InputMode, ReturnType<typeof setTimeout>>>>({});
  const requestFiles = useCallback((mode: InputMode) => {
    clearTimeout(fileTimers.current[mode]);
    setFileStatuses((previous) => ({ ...previous, [mode]: 'loading' }));
    socket.send({ topic: fileTopic(mode) });
    fileTimers.current[mode] = setTimeout(
      () => setFileStatuses((previous) => (previous[mode] === 'loading' ? { ...previous, [mode]: 'error' } : previous)),
      12000,
    );
  }, []);
  useEffect(() => {
    const receiveFiles = (mode: InputMode) => (data: any) => {
      clearTimeout(fileTimers.current[mode]);
      if (!Array.isArray(data.files)) {
        setFileStatuses((previous) => ({ ...previous, [mode]: 'error' }));
        return;
      }
      setFiles((previous) => ({ ...previous, [mode]: normalizeQueryFiles(data.files) }));
      setFileStatuses((previous) => ({ ...previous, [mode]: 'ready' }));
    };
    const connection = (data: any) => {
      if (data.status === 'connected') {
        setError('');
        requestFiles('custom');
        requestFiles('llm-generated');
      } else if (['disconnected', 'error', 'reconnecting'].includes(data.status)) {
        setError(typeof data.message === 'string' ? data.message : '서버 연결을 확인하세요.');
        setFileStatuses((previous) => ({
          custom: previous.custom === 'loading' ? 'error' : previous.custom,
          'llm-generated': previous['llm-generated'] === 'loading' ? 'error' : previous['llm-generated'],
        }));
      }
    };
    const listeners = {
      'generated-query-files': receiveFiles('llm-generated'),
      'custom-query-files': receiveFiles('custom'),
      'connection-state': connection,
    };
    Object.entries(listeners).forEach(([topic, callback]) => socket.on(topic, callback));
    socket.subscribe(['generated-query-files', 'custom-query-files']);
    return () => {
      Object.entries(listeners).forEach(([topic, callback]) => socket.off(topic, callback));
      Object.values(fileTimers.current).forEach((timer) => clearTimeout(timer));
    };
  }, [requestFiles]);
  useEffect(() => {
    setSelectedFileName('');
    requestFiles(inputMode);
  }, [inputMode, requestFiles]);
  const currentFiles = useMemo(() => files[inputMode], [files, inputMode]);
  useEffect(() => {
    if (fileStatuses[inputMode] === 'ready' && selectedFileName && !currentFiles.includes(selectedFileName))
      setSelectedFileName('');
  }, [currentFiles, fileStatuses, inputMode, selectedFileName]);
  useEffect(() => {
    if (request && requestFinished(request) && request.result && !request.navigationHandled) {
      socket.acknowledgeRequest(request.id);
      navigate('/dashboard', { state: { requestId: request.id } });
    }
  }, [request, navigate]);
  const busy = !!request && !requestFinished(request) && request.status !== 'unknown';
  const isRunning = busy && !request?.disconnected;
  const recoveryNeeded = requestNeedsRecovery(request);
  const run = () => {
    if (busy || recoveryNeeded) return;
    if (fileStatuses[inputMode] !== 'ready' || !currentFiles.includes(selectedFileName)) {
      setError('목록에 있는 질문 파일을 선택한 뒤 실행하세요.');
      return;
    }
    const sent = start(inputMode === 'llm-generated' ? 'run-rag-llm-query' : 'run-rag-file-query', {
      settings: { file_name: selectedFileName },
    });
    setError(sent ? '' : '서버에 연결되지 않아 실행 요청을 보내지 않았습니다. 연결을 확인한 뒤 다시 실행하세요.');
  };
  const total = request?.totalQueries || 0,
    completed = request?.completedQueryIds.length || 0;
  const message = request
    ? `${request.label} · ${requestStatusText(request)}${total > 0 ? ` (${completed}/${total}건 종료)` : ''}`
    : '';
  return (
    <>
      <SettingsView
        step={step}
        isRunning={isRunning}
        progress={evaluationProgress(completed, total)}
        progressMessage={message}
        totalQueries={total}
        recoveryNeeded={recoveryNeeded}
        requestLabel={request?.label}
        requestMessage={request ? requestStatusText(request) : undefined}
        handleCheckResults={() => request && socket.refreshRequest(request.id)}
        handleOpenDashboard={() => navigate('/dashboard')}
        handlePrepareNewRun={() => {
          clear();
          setError('');
        }}
        inputMode={inputMode}
        setInputMode={setInputMode}
        serverFiles={currentFiles}
        fileStatus={fileStatuses[inputMode]}
        error={error || request?.error || request?.warning || ''}
        selectedFileName={busy || recoveryNeeded ? request?.input || '' : selectedFileName}
        setSelectedFileName={setSelectedFileName}
        handleNextStep={() => (step === 1 ? setStep(2) : run())}
        handlePrevStep={() => setStep(1)}
        handleRefresh={() => {
          setError('');
          requestFiles(inputMode);
        }}
      />
      {request && (
        <TechnicalDetails
          entries={[
            ['요청 ID', request.id],
            ['요청 상태 원본', request.status],
            ['질문 ID', request.queryIds],
            ['실행 ID', request.runIds],
          ]}
        />
      )}
    </>
  );
};
