export type ChartDomain = [number | 'auto', number | 'auto'];

/** Declared bounds guide the axis; real observations may expand them and are never converted. */
export function declaredUnitDomain(unit: string | undefined, values: unknown[]): ChartDomain {
  if (unit !== '0 to 1') return ['auto', 'auto'];
  return values.reduce<[number, number]>(
    (domain, value) =>
      typeof value === 'number' && Number.isFinite(value)
        ? [Math.min(domain[0], value), Math.max(domain[1], value)]
        : domain,
    [0, 1],
  );
}
